-- MTH 121 (Elementary Mathematics II, UNN) practice questions for the CBT feature.
-- Source: real worked calculus questions supplied by the user (functions, limits,
-- continuity, differentiation, integration). Every question's explanation is a
-- genuine sympy-verified step-by-step derivation (not just a name-the-rule
-- statement) -- see the "gen_explanations.py" generation script. Every field
-- (question, options, explanation) is fully rendered in LaTeX: every word is
-- individually wrapped in its own $...$ span (math as real notation, prose in
-- 	ext{}), joined by literal spaces so MathText can still line-wrap normally --
-- wrapping a whole multi-sentence field in ONE $...$ span makes it one atomic,
-- unbreakable widget that overflows on any real screen width, so this is
-- word-by-word instead. Long unbroken equality/addition chains are further
-- split into several $...$ spans at top-level '=' or '+'/'-' so a long
-- derivation still has line-wrap opportunities within it.
--
-- One question was dropped: the definite integral of 1/[(x-1)(x+2)] from 0 to 1
-- has a singularity at x=1 (the upper bound), so it diverges and none of the
-- supplied answer choices are mathematically valid.
--
-- cbt_questions has no course_code column, so the MTH 121 link lives in
-- subject_name. is_general = false and faculty is pinned to 'Faculty of
-- Physical Sciences' so only students in that faculty see this paper.

delete from public.cbt_questions where subject_id = 'mth-121-calculus';

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
