values
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 2x-3$$\text{,}$ $g(x) = x^2+1$$\text{,}$ $\text{find}$ $(f \circ g)(2)$$\text{.}$', '["$5$", "$7$", "$6$", "$2$"]'::jsonb, 1, '$(f \circ g)(2) = f(g(2))$$\text{.}$ $\text{First}$ $\text{find}$ $g(2)$ $\text{by}$ $\text{substituting}$ $x=2$ $\text{into}$ $g(x) = x^{2} + 1$$\text{:}$ $g(2) = 2^{2} + 1 = 5$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(2) = 5$ $\text{into}$ $f(x) = 2 x - 3$$\text{:}$ $f(5) = 2 \cdot 5 - 3 = 7$$\text{.}$ $\text{So}$ $(f \circ g)(2) = 7$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^2$$\text{,}$ $g(x) = 3x-1$$\text{,}$ $\text{find}$ $(f \circ g)(1)$$\text{.}$', '["$5$", "$2$", "$4$", "$3$"]'::jsonb, 2, '$(f \circ g)(1) = f(g(1))$$\text{.}$ $\text{First}$ $\text{find}$ $g(1)$ $\text{by}$ $\text{substituting}$ $x=1$ $\text{into}$ $g(x) = 3 x - 1$$\text{:}$ $g(1) = 3 \cdot 1 - 1 = 2$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(1) = 2$ $\text{into}$ $f(x) = x^{2}$$\text{:}$ $f(2) = 2^{2} = 4$$\text{.}$ $\text{So}$ $(f \circ g)(1) = 4$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = |x|$$\text{,}$ $g(x) = 2x-5$$\text{,}$ $\text{find}$ $(f \circ g)(1)$$\text{.}$', '["$3$", "$-2$", "$-3$", "$4$"]'::jsonb, 0, '$(f \circ g)(1) = f(g(1))$$\text{.}$ $\text{First}$ $\text{find}$ $g(1)$ $\text{by}$ $\text{substituting}$ $x=1$ $\text{into}$ $g(x) = 2 x - 5$$\text{:}$ $g(1) = 2 \cdot 1 - 5 = -3$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(1) = -3$ $\text{into}$ $f(x) = \left|{x}\right|$$\text{:}$ $f(-3) = \left|{-3}\right| = 3$$\text{.}$ $\text{So}$ $(f \circ g)(1) = 3$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 3x+4$$\text{,}$ $g(x) = x^2-2x$$\text{,}$ $\text{find}$ $(f \circ g)(3)$$\text{.}$', '["$16$", "$3$", "$13$", "$143$"]'::jsonb, 2, '$(f \circ g)(3) = f(g(3))$$\text{.}$ $\text{First}$ $\text{find}$ $g(3)$ $\text{by}$ $\text{substituting}$ $x=3$ $\text{into}$ $g(x) = x^{2} - 2 x$$\text{:}$ $g(3) = 3^{2} - 2 \cdot 3 = 3$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(3) = 3$ $\text{into}$ $f(x) = 3 x + 4$$\text{:}$ $f(3) = 3 \cdot 3 + 4 = 13$$\text{.}$ $\text{So}$ $(f \circ g)(3) = 13$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^2-1$$\text{,}$ $g(x) = x+2$$\text{,}$ $\text{find}$ $(f \circ g)(-1)$$\text{.}$', '["$-1$", "$1$", "$2$", "$0$"]'::jsonb, 3, '$(f \circ g)(-1) = f(g(-1))$$\text{.}$ $\text{First}$ $\text{find}$ $g(-1)$ $\text{by}$ $\text{substituting}$ $x=-1$ $\text{into}$ $g(x) = x + 2$$\text{:}$ $g(-1) = -1 + 2 = 1$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(-1) = 1$ $\text{into}$ $f(x) = x^{2} - 1$$\text{:}$ $f(1) = 1^{2} - 1 = 0$$\text{.}$ $\text{So}$ $(f \circ g)(-1) = 0$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 5-x$$\text{,}$ $g(x) = x^2$$\text{,}$ $\text{find}$ $(f \circ g)(3)$$\text{.}$', '["$9$", "$4$", "$11$", "$-4$"]'::jsonb, 3, '$(f \circ g)(3) = f(g(3))$$\text{.}$ $\text{First}$ $\text{find}$ $g(3)$ $\text{by}$ $\text{substituting}$ $x=3$ $\text{into}$ $g(x) = x^{2}$$\text{:}$ $g(3) = 3^{2} = 9$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(3) = 9$ $\text{into}$ $f(x) = 5 - x$$\text{:}$ $f(9) = 5 - 9 = -4$$\text{.}$ $\text{So}$ $(f \circ g)(3) = -4$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^3$$\text{,}$ $g(x) = x-1$$\text{,}$ $\text{find}$ $(f \circ g)(2)$$\text{.}$', '["$7$", "$1$", "$2$", "$9$"]'::jsonb, 1, '$(f \circ g)(2) = f(g(2))$$\text{.}$ $\text{First}$ $\text{find}$ $g(2)$ $\text{by}$ $\text{substituting}$ $x=2$ $\text{into}$ $g(x) = x - 1$$\text{:}$ $g(2) = 2 - 1 = 1$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(2) = 1$ $\text{into}$ $f(x) = x^{3}$$\text{:}$ $f(1) = 1^{3} = 1$$\text{.}$ $\text{So}$ $(f \circ g)(2) = 1$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 4-2x$$\text{,}$ $g(x) = x^2+3$$\text{,}$ $\text{find}$ $(f \circ g)(1)$$\text{.}$', '["$6$", "$4$", "$7$", "$-4$"]'::jsonb, 3, '$(f \circ g)(1) = f(g(1))$$\text{.}$ $\text{First}$ $\text{find}$ $g(1)$ $\text{by}$ $\text{substituting}$ $x=1$ $\text{into}$ $g(x) = x^{2} + 3$$\text{:}$ $g(1) = 1^{2} + 3 = 4$$\text{.}$ $\text{Then}$ $\text{substitute}$ $g(1) = 4$ $\text{into}$ $f(x) = 4 - 2 x$$\text{:}$ $f(4) = 4 - 2 \cdot 4 = -4$$\text{.}$ $\text{So}$ $(f \circ g)(1) = -4$$\text{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 2x+1$$\text{,}$ $g(x) = x^2$$\text{,}$ $\text{find}$ $(f+g)(3)$$\text{.}$', '["$-2$", "$63$", "$7$", "$16$"]'::jsonb, 3, '$(f+g)(3) = f(3) + g(3)$$\text{.}$ $\text{Substituting}$ $x=3$$\text{:}$ $f(3) = 2 \cdot 3 + 1 = 7$ $\text{and}$ $g(3) = 3^{2} = 9$$\text{,}$ $\text{so}$ $(f+g)(3) = 7 + 9 = 16$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 2x+1$$\text{,}$ $g(x) = x^2$$\text{,}$ $\text{find}$ $(f \cdot g)(3)$$\text{.}$', '["$16$", "$63$", "$-2$", "$9$"]'::jsonb, 1, '$(f \cdot g)(3) = f(3) \cdot g(3)$$\text{.}$ $\text{Substituting}$ $x=3$$\text{:}$ $f(3) = 2 \cdot 3 + 1 = 7$ $\text{and}$ $g(3) = 3^{2} = 9$$\text{,}$ $\text{so}$ $(f \cdot g)(3) = 7 \cdot 9 = 63$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^2-4$$\text{,}$ $g(x) = x+2$$\text{,}$ $\text{find}$ $(f+g)(1)$$\text{.}$', '["$-6$", "$0$", "$-9$", "$-3$"]'::jsonb, 1, '$(f+g)(1) = f(1) + g(1)$$\text{.}$ $\text{Substituting}$ $x=1$$\text{:}$ $f(1) = 1^{2} - 4 = -3$ $\text{and}$ $g(1) = 1 + 2 = 3$$\text{,}$ $\text{so}$ $(f+g)(1) = -3 + 3 = 0$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^2-4$$\text{,}$ $g(x) = x+2$$\text{,}$ $\text{find}$ $(f \cdot g)(1)$$\text{.}$', '["$-9$", "$-6$", "$3$", "$0$"]'::jsonb, 0, '$(f \cdot g)(1) = f(1) \cdot g(1)$$\text{.}$ $\text{Substituting}$ $x=1$$\text{:}$ $f(1) = 1^{2} - 4 = -3$ $\text{and}$ $g(1) = 1 + 2 = 3$$\text{,}$ $\text{so}$ $(f \cdot g)(1) = -3 \cdot 3 = -9$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 3x$$\text{,}$ $g(x) = x-5$$\text{,}$ $\text{find}$ $(f+g)(4)$$\text{.}$', '["$-12$", "$11$", "$12$", "$13$"]'::jsonb, 1, '$(f+g)(4) = f(4) + g(4)$$\text{.}$ $\text{Substituting}$ $x=4$$\text{:}$ $f(4) = 3 \cdot 4 = 12$ $\text{and}$ $g(4) = 4 - 5 = -1$$\text{,}$ $\text{so}$ $(f+g)(4) = 12 + -1 = 11$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = 3x$$\text{,}$ $g(x) = x-5$$\text{,}$ $\text{find}$ $(f \cdot g)(4)$$\text{.}$', '["$-12$", "$13$", "$-1$", "$11$"]'::jsonb, 0, '$(f \cdot g)(4) = f(4) \cdot g(4)$$\text{.}$ $\text{Substituting}$ $x=4$$\text{:}$ $f(4) = 3 \cdot 4 = 12$ $\text{and}$ $g(4) = 4 - 5 = -1$$\text{,}$ $\text{so}$ $(f \cdot g)(4) = 12 \cdot -1 = -12$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^2+2$$\text{,}$ $g(x) = 2x-1$$\text{,}$ $\text{find}$ $(f+g)(2)$$\text{.}$', '["$18$", "$6$", "$3$", "$9$"]'::jsonb, 3, '$(f+g)(2) = f(2) + g(2)$$\text{.}$ $\text{Substituting}$ $x=2$$\text{:}$ $f(2) = 2^{2} + 2 = 6$ $\text{and}$ $g(2) = 2 \cdot 2 - 1 = 3$$\text{,}$ $\text{so}$ $(f+g)(2) = 6 + 3 = 9$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Given}$ $f(x) = x^2+2$$\text{,}$ $g(x) = 2x-1$$\text{,}$ $\text{find}$ $(f \cdot g)(2)$$\text{.}$', '["$18$", "$19$", "$3$", "$9$"]'::jsonb, 0, '$(f \cdot g)(2) = f(2) \cdot g(2)$$\text{.}$ $\text{Substituting}$ $x=2$$\text{:}$ $f(2) = 2^{2} + 2 = 6$ $\text{and}$ $g(2) = 2 \cdot 2 - 1 = 3$$\text{,}$ $\text{so}$ $(f \cdot g)(2) = 6 \cdot 3 = 18$$\text{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 3x-4$$\text{,}$ $\text{find}$ $f^{-1}(5)$$\text{.}$', '["$27$", "$1/3$", "$11$", "$3$"]'::jsonb, 3, '$\text{To}$ $\text{find}$ $f^{-1}(5)$$\text{,}$ $\text{solve}$ $f(x) = 5$ $\text{for}$ $x$$\text{:}$ $3 x - 4 = 5$$\text{.}$ $\text{Rearranging}$ $\text{gives}$ $x = 3$$\text{,}$ $\text{so}$ $f^{-1}(5) = 3$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 2x+7$$\text{,}$ $\text{find}$ $f^{-1}(3)$$\text{.}$', '["$5$", "$-2$", "$13$", "$-8$"]'::jsonb, 1, '$\text{To}$ $\text{find}$ $f^{-1}(3)$$\text{,}$ $\text{solve}$ $f(x) = 3$ $\text{for}$ $x$$\text{:}$ $2 x + 7 = 3$$\text{.}$ $\text{Rearranging}$ $\text{gives}$ $x = -2$$\text{,}$ $\text{so}$ $f^{-1}(3) = -2$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = -x+6$$\text{,}$ $\text{find}$ $f^{-1}(2)$$\text{.}$', '["$4$", "$3$", "$-8$", "$5$"]'::jsonb, 0, '$\text{To}$ $\text{find}$ $f^{-1}(2)$$\text{,}$ $\text{solve}$ $f(x) = 2$ $\text{for}$ $x$$\text{:}$ $6 - x = 2$$\text{.}$ $\text{Rearranging}$ $\text{gives}$ $x = 4$$\text{,}$ $\text{so}$ $f^{-1}(2) = 4$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 5x+1$$\text{,}$ $\text{find}$ $f^{-1}(11)$$\text{.}$', '["$12/5$", "$2$", "$56$", "$50$"]'::jsonb, 1, '$\text{To}$ $\text{find}$ $f^{-1}(11)$$\text{,}$ $\text{solve}$ $f(x) = 11$ $\text{for}$ $x$$\text{:}$ $5 x + 1 = 11$$\text{.}$ $\text{Rearranging}$ $\text{gives}$ $x = 2$$\text{,}$ $\text{so}$ $f^{-1}(11) = 2$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 4x-3$$\text{,}$ $\text{find}$ $f^{-1}(9)$$\text{.}$', '["$33$", "$3/2$", "$3$", "$48$"]'::jsonb, 2, '$\text{To}$ $\text{find}$ $f^{-1}(9)$$\text{,}$ $\text{solve}$ $f(x) = 9$ $\text{for}$ $x$$\text{:}$ $4 x - 3 = 9$$\text{.}$ $\text{Rearranging}$ $\text{gives}$ $x = 3$$\text{,}$ $\text{so}$ $f^{-1}(9) = 3$$\text{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{What}$ $\text{is}$ $\text{the}$ $\text{domain}$ $\text{of}$ $f(x) = 1/(x-3)?$', '["$\\text{R}$", "$\\text{R}$ $\\text{except}$ $\\text{x}$ $\\text{=}$ $\\text{3}$", "$x > 3$ $\\text{only}$", "$x < 3$ $\\text{only}$"]'::jsonb, 1, '$\text{For}$ $f(x) = \frac{1}{x - 3}$ $\text{to}$ $\text{be}$ $\text{defined,}$ $\text{the}$ $\text{denominator}$ $\text{must}$ $\text{not}$ $\text{be}$ $\text{zero:}$ $x - 3 \neq 0$$\text{,}$ $\text{which}$ $\text{excludes}$ $x = 3$$\text{.}$ $\text{Combining}$ $\text{these}$ $\text{conditions,}$ $\text{the}$ $\text{domain}$ $\text{is}$ $\left(-\infty, 3\right) \cup \left(3, \infty\right)$$\text{.}$', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{What}$ $\text{is}$ $\text{the}$ $\text{domain}$ $\text{of}$ $f(x) = \sqrt{x-2}?$', '["$x \\geq 2$", "$x > 2$", "$\\text{all}$ $\\text{real}$ $\\text{x}$", "$x \\leq 2$"]'::jsonb, 0, '$\text{For}$ $f(x) = \sqrt{x - 2}$ $\text{to}$ $\text{be}$ $\text{defined,}$ $\text{the}$ $\text{expression}$ $\text{under}$ $\text{the}$ $\text{square}$ $\text{root}$ $\text{must}$ $\text{be}$ $\text{non-negative:}$ $x - 2 \geq 0$$\text{,}$ $\text{which}$ $\text{gives}$ $\left[2, \infty\right)$$\text{.}$ $\text{Combining}$ $\text{these}$ $\text{conditions,}$ $\text{the}$ $\text{domain}$ $\text{is}$ $\left[2, \infty\right)$$\text{.}$', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{What}$ $\text{is}$ $\text{the}$ $\text{domain}$ $\text{of}$ $f(x) = 1/\sqrt{x+5}?$', '["$x < -5$", "$\\text{all}$ $\\text{real}$ $\\text{x}$", "$x \\geq -5$", "$x > -5$"]'::jsonb, 3, '$\text{For}$ $f(x) = \frac{1}{\sqrt{x + 5}}$ $\text{to}$ $\text{be}$ $\text{defined,}$ $\text{the}$ $\text{denominator}$ $\text{must}$ $\text{not}$ $\text{be}$ $\text{zero:}$ $\sqrt{x + 5} \neq 0$$\text{,}$ $\text{which}$ $\text{excludes}$ $x = -5$$\text{.}$ $\text{Combining}$ $\text{these}$ $\text{conditions,}$ $\text{the}$ $\text{domain}$ $\text{is}$ $\left(-5, \infty\right)$$\text{.}$', 'Real-valued Functions of a Real Variable', false),
