  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{What}$ $\text{is}$ $\text{the}$ $\text{domain}$ $\text{of}$ $f(x) = 1/(x^2-4)?$', '["$\\text{all}$ $\\text{real}$ $\\text{x}$", "$\\text{R}$ $\\text{except}$ $\\text{x}$ $\\text{=}$ $\\text{2}$ $\\text{and}$ $\\text{x}$ $\\text{=}$ $\\text{-2}$", "$\\text{R}$ $\\text{except}$ $\\text{x}$ $\\text{=}$ $\\text{2}$", "$\\text{R}$ $\\text{except}$ $\\text{x}$ $\\text{=}$ $\\text{-2}$"]'::jsonb, 1, '$\text{For}$ $f(x) = \frac{1}{x^{2} - 4}$ $\text{to}$ $\text{be}$ $\text{defined,}$ $\text{the}$ $\text{denominator}$ $\text{must}$ $\text{not}$ $\text{be}$ $\text{zero:}$ $x^{2} - 4 \neq 0$$\text{,}$ $\text{which}$ $\text{excludes}$ $x = -2 \text{ and } x = 2$$\text{.}$ $\text{Combining}$ $\text{these}$ $\text{conditions,}$ $\text{the}$ $\text{domain}$ $\text{is}$ $\left(-\infty, -2\right) \cup \left(-2, 2\right) \cup \left(2, \infty\right)$$\text{.}$', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{What}$ $\text{is}$ $\text{the}$ $\text{domain}$ $\text{of}$ $f(x) = \sqrt{x+1}/(x-4)?$', '["$x \\geq -1$", "$x > -1$", "$x \\geq -1, x \\neq 4$", "$\\text{all}$ $\\text{real}$ $\\text{x}$"]'::jsonb, 2, '$\text{For}$ $f(x) = \frac{\sqrt{x + 1}}{x - 4}$ $\text{to}$ $\text{be}$ $\text{defined,}$ $\text{the}$ $\text{denominator}$ $\text{must}$ $\text{not}$ $\text{be}$ $\text{zero:}$ $x - 4 \neq 0$$\text{,}$ $\text{which}$ $\text{excludes}$ $x = 4$$\text{;}$ $\text{and}$ $\text{the}$ $\text{expression}$ $\text{under}$ $\text{the}$ $\text{square}$ $\text{root}$ $\text{must}$ $\text{be}$ $\text{non-negative:}$ $x + 1 \geq 0$$\text{,}$ $\text{which}$ $\text{gives}$ $\left[-1, \infty\right)$$\text{.}$ $\text{Combining}$ $\text{these}$ $\text{conditions,}$ $\text{the}$ $\text{domain}$ $\text{is}$ $\left[-1, 4\right) \cup \left(4, \infty\right)$$\text{.}$', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [3x^2 - 5x + 7]$$\text{.}$', '["$10$", "$-9$", "$7$", "$9$"]'::jsonb, 3, '$\text{Since}$ $f(x) = 3 x^{2} - 5 x + 7$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=2$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to 2} 3 x^{2} - 5 x + 7$ = $3 \cdot 2^{2} - 5 \cdot 2 + 7$ = $9$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to -1} [x^3 - 4x + 1]$$\text{.}$', '["$-1$", "$5$", "$4$", "$-4$"]'::jsonb, 2, '$\text{Since}$ $f(x) = x^{3} - 4 x + 1$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=-1$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to -1} x^{3} - 4 x + 1$ = $\left(-1\right)^{3}$ - $4 \left(-1\right)$ + $1$ = $4$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 4} [(2x + 3)/(x - 1)]$$\text{.}$', '["$14/3$", "$11/3$", "$-5/9$", "$-11/3$"]'::jsonb, 1, '$\text{Since}$ $f(x) = \frac{2 x + 3}{x - 1}$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=4$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to 4} \frac{2 x + 3}{x - 1}$ = $\frac{2 \cdot 4 + 3}{4 - 1}$ = $\frac{11}{3}$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 1} [(x^2 - 1)/(x + 3)]$$\text{.}$', '["$1$", "$-1$", "$1/2$", "$0$"]'::jsonb, 3, '$\text{Since}$ $f(x) = \frac{x^{2} - 1}{x + 3}$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=1$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to 1} \frac{x^{2} - 1}{x + 3}$ = $\frac{1^{2} - 1}{1 + 3}$ = $0$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 3} [5x - 7]$$\text{.}$', '["$8$", "$9$", "$-8$", "$5$"]'::jsonb, 0, '$\text{Since}$ $f(x) = 5 x - 7$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=3$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to 3} 5 x - 7$ = $5 \cdot 3 - 7$ = $8$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to -2} [(x^2 + 2x)/(x + 5)]$$\text{.}$', '["$0$", "$1$", "$-1$", "$-2/3$"]'::jsonb, 0, '$\text{Since}$ $f(x) = \frac{x^{2} + 2 x}{x + 5}$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=-2$ $\text{(the}$ $\text{denominator,}$ $\text{if}$ $\text{any,}$ $\text{is}$ $\text{not}$ $\text{zero}$ $\text{there),}$ $\text{substitute}$ $\text{directly:}$ $\lim_{x \to -2} \frac{x^{2} + 2 x}{x + 5}$ = $\frac{\left(-2\right) \left(2 + -2\right)}{-2 + 5}$ = $0$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 3} [(x^2 - 9)/(x - 3)]$$\text{.}$', '["$0$", "$8$", "$6$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(∞)}$"]'::jsonb, 2, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 9}{x - 3}$ = $\dfrac{\left(x - 3\right) \left(x + 3\right)}{x - 3}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x + 3$ $\text{(valid}$ $\text{for}$ $x \neq 3$$\text{).}$ $\text{Substituting}$ $x=3$$\text{:}$ $3 + 3 = 6$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [(x^2 - 4)/(x - 2)]$$\text{.}$', '["$4$", "$6$", "$0$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(∞)}$"]'::jsonb, 0, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 4}{x - 2}$ = $\dfrac{\left(x - 2\right) \left(x + 2\right)}{x - 2}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x + 2$ $\text{(valid}$ $\text{for}$ $x \neq 2$$\text{).}$ $\text{Substituting}$ $x=2$$\text{:}$ $2 + 2 = 4$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [(x^2 - 5x + 6)/(x - 2)]$$\text{.}$', '["$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(∞)}$", "$-1$", "$0$", "$1$"]'::jsonb, 1, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 5 x + 6}{x - 2}$ = $\dfrac{\left(x - 3\right) \left(x - 2\right)}{x - 2}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x - 3$ $\text{(valid}$ $\text{for}$ $x \neq 2$$\text{).}$ $\text{Substituting}$ $x=2$$\text{:}$ $2 - 3 = -1$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 1} [(x^2 - 1)/(x - 1)]$$\text{.}$', '["$4$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(∞)}$", "$2$", "$0$"]'::jsonb, 2, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} - 1}{x - 1}$ = $\dfrac{\left(x - 1\right) \left(x + 1\right)}{x - 1}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x + 1$ $\text{(valid}$ $\text{for}$ $x \neq 1$$\text{).}$ $\text{Substituting}$ $x=1$$\text{:}$ $1 + 1 = 2$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [(x^3 - 8)/(x - 2)]$$\text{.}$', '["$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(∞)}$", "$0$", "$14$", "$12$"]'::jsonb, 3, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{3} - 8}{x - 2}$ = $\dfrac{\left(x - 2\right) \left(x^{2} + 2 x + 4\right)}{x - 2}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x^{2} + 2 x + 4$ $\text{(valid}$ $\text{for}$ $x \neq 2$$\text{).}$ $\text{Substituting}$ $x=2$$\text{:}$ $2^{2} + 2 \cdot 2 + 4 = 12$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 2} [(x^2 + x - 6)/(x - 2)]$$\text{.}$', '["$\\text{does}$ $\\text{not}$ $\\text{exist}$ $\\text{(∞)}$", "$7$", "$5$", "$0$"]'::jsonb, 2, '$\text{Direct}$ $\text{substitution}$ $\text{gives}$ $\frac{0}{0}$$\text{,}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Factor:}$ $\dfrac{x^{2} + x - 6}{x - 2}$ = $\dfrac{\left(x - 2\right) \left(x + 3\right)}{x - 2}$$\text{,}$ $\text{and}$ $\text{cancel}$ $\text{the}$ $\text{common}$ $\text{factor}$ $\text{to}$ $\text{get}$ $x + 3$ $\text{(valid}$ $\text{for}$ $x \neq 2$$\text{).}$ $\text{Substituting}$ $x=2$$\text{:}$ $2 + 3 = 5$$\text{.}$', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to \infty} [(2x^2 + 3x)/(5x^2 - x + 1)]$$\text{.}$', '["$2/5$", "$\\text{∞}$ $\\text{(does}$ $\\text{not}$ $\\text{exist)}$", "$1$", "$0$"]'::jsonb, 0, '$\text{Divide}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x^{2}$$\text{,}$ $\text{the}$ $\text{highest}$ $\text{power}$ $\text{of}$ $x$ $\text{present:}$ $\dfrac{x \left(2 x + 3\right)}{5 x^{2} - x + 1}$ = $\dfrac{2 + \frac{3}{x}}{5 - \frac{1}{x} + \frac{1}{x^{2}}}$$\text{.}$ $\text{As}$ $x \to \infty$$\text{,}$ $\text{every}$ $\text{term}$ $\text{with}$ $x$ $\text{in}$ $\text{the}$ $\text{denominator}$ $\text{goes}$ $\text{to}$ $0$$\text{,}$ $\text{leaving}$ $\lim_{x \to \infty} \frac{2 x^{2} + 3 x}{5 x^{2} - x + 1}$ = $\frac{2}{5}$$\text{.}$', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to \infty} [(3x + 1)/(6x + 5)]$$\text{.}$', '["$1/2$", "$0$", "$1$", "$\\text{∞}$ $\\text{(does}$ $\\text{not}$ $\\text{exist)}$"]'::jsonb, 0, '$\text{Divide}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x^{1}$$\text{,}$ $\text{the}$ $\text{highest}$ $\text{power}$ $\text{of}$ $x$ $\text{present:}$ $\dfrac{3 x + 1}{6 x + 5}$ = $\dfrac{3 + \frac{1}{x}}{6 + \frac{5}{x}}$$\text{.}$ $\text{As}$ $x \to \infty$$\text{,}$ $\text{every}$ $\text{term}$ $\text{with}$ $x$ $\text{in}$ $\text{the}$ $\text{denominator}$ $\text{goes}$ $\text{to}$ $0$$\text{,}$ $\text{leaving}$ $\lim_{x \to \infty} \frac{3 x + 1}{6 x + 5}$ = $\frac{1}{2}$$\text{.}$', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to \infty} [(x^2 + 1)/(x^3 + 2)]$$\text{.}$', '["$-1$", "$0$", "$1$", "$\\text{∞}$ $\\text{(does}$ $\\text{not}$ $\\text{exist)}$"]'::jsonb, 1, '$\text{Divide}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x^{3}$$\text{,}$ $\text{the}$ $\text{highest}$ $\text{power}$ $\text{of}$ $x$ $\text{present:}$ $\dfrac{x^{2} + 1}{x^{3} + 2}$ = $\dfrac{\frac{1}{x} + \frac{1}{x^{3}}}{1 + \frac{2}{x^{3}}}$$\text{.}$ $\text{As}$ $x \to \infty$$\text{,}$ $\text{every}$ $\text{term}$ $\text{with}$ $x$ $\text{in}$ $\text{the}$ $\text{denominator}$ $\text{goes}$ $\text{to}$ $0$$\text{,}$ $\text{leaving}$ $\lim_{x \to \infty} \frac{x^{2} + 1}{x^{3} + 2}$ = $0$$\text{.}$', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to \infty} [(4x^3 - x)/(2x^3 + 7)]$$\text{.}$', '["$2$", "$0$", "$\\text{∞}$ $\\text{(does}$ $\\text{not}$ $\\text{exist)}$", "$1$"]'::jsonb, 0, '$\text{Divide}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x^{3}$$\text{,}$ $\text{the}$ $\text{highest}$ $\text{power}$ $\text{of}$ $x$ $\text{present:}$ $\dfrac{x \left(4 x^{2} - 1\right)}{2 x^{3} + 7}$ = $\dfrac{4 - \frac{1}{x^{2}}}{2 + \frac{7}{x^{3}}}$$\text{.}$ $\text{As}$ $x \to \infty$$\text{,}$ $\text{every}$ $\text{term}$ $\text{with}$ $x$ $\text{in}$ $\text{the}$ $\text{denominator}$ $\text{goes}$ $\text{to}$ $0$$\text{,}$ $\text{leaving}$ $\lim_{x \to \infty} \frac{4 x^{3} - x}{2 x^{3} + 7}$ = $2$$\text{.}$', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to \infty} [(x + 3)/(x^2 - 4)]$$\text{.}$', '["$0$", "$\\text{∞}$ $\\text{(does}$ $\\text{not}$ $\\text{exist)}$", "$-1$", "$1$"]'::jsonb, 0, '$\text{Divide}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{by}$ $x^{2}$$\text{,}$ $\text{the}$ $\text{highest}$ $\text{power}$ $\text{of}$ $x$ $\text{present:}$ $\dfrac{x + 3}{x^{2} - 4}$ = $\dfrac{\frac{1}{x} + \frac{3}{x^{2}}}{1 - \frac{4}{x^{2}}}$$\text{.}$ $\text{As}$ $x \to \infty$$\text{,}$ $\text{every}$ $\text{term}$ $\text{with}$ $x$ $\text{in}$ $\text{the}$ $\text{denominator}$ $\text{goes}$ $\text{to}$ $0$$\text{,}$ $\text{leaving}$ $\lim_{x \to \infty} \frac{x + 3}{x^{2} - 4}$ = $0$$\text{.}$', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 3-x$ $\text{for}$ $x < 2$ $\text{and}$ $f(x) = x^2-1$ $\text{for}$ $x \geq 2$$\text{,}$ $\text{find}$ $\lim_{x \to 2⁻}$  $\text{f(x).}$', '["$1$", "$3$", "$0$", "$-1$"]'::jsonb, 0, '$\text{Approaching}$ $x=2$ $\text{from}$ $\text{below,}$ $x < 2$ $\text{applies,}$ $\text{so}$ $f(x) = 3 - x$ $\text{is}$ $\text{the}$ $\text{relevant}$ $\text{branch.}$ $\text{The}$ $\text{left-hand}$ $\text{limit}$ $\text{is}$ $\lim_{x \to 2^-} f(x) = 3 - 2 = 1$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = 3-x$ $\text{for}$ $x < 2$ $\text{and}$ $f(x) = x^2-1$ $\text{for}$ $x \geq 2$$\text{,}$ $\text{find}$ $\lim_{x \to 2⁺}$  $\text{f(x).}$', '["$3$", "$4$", "$1$", "$0$"]'::jsonb, 0, '$\text{Approaching}$ $x=2$ $\text{from}$ $\text{above,}$ $x \geq 2$ $\text{applies,}$ $\text{so}$ $f(x) = x^{2} - 1$ $\text{is}$ $\text{the}$ $\text{relevant}$ $\text{branch.}$ $\text{The}$ $\text{right-hand}$ $\text{limit}$ $\text{is}$ $\lim_{x \to 2^+} f(x) = 2^{2} - 1 = 3$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $\text{the}$ $\text{greatest}$ $\text{integer}$ $\text{function}$ $f(x) = [x]$$\text{,}$ $\text{find}$ $\lim_{x \to 3⁻}$  $\text{f(x).}$', '["$4$", "$2$", "$3$", "$0$"]'::jsonb, 1, '$\text{Just}$ $\text{below}$ $3$$\text{,}$ $\text{on}$ $\text{the}$ $\text{interval}$ $[2, 3)$$\text{,}$ $\text{the}$ $\text{greatest}$ $\text{integer}$ $\text{function}$ $[x]$ $\text{stays}$ $\text{constant}$ $\text{at}$ $2$ $\text{—}$ $\text{it}$ $\text{only}$ $\text{steps}$ $\text{up}$ $\text{to}$ $3$ $\text{once}$ $x$ $\text{reaches}$ $3$ $\text{itself.}$ $\text{So}$ $\text{the}$ $\text{left-hand}$ $\text{limit}$ $\text{is}$ $\lim_{x \to 3^-} [x] = 2$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $\text{the}$ $\text{greatest}$ $\text{integer}$ $\text{function}$ $f(x) = [x]$$\text{,}$ $\text{find}$ $\lim_{x \to 3⁺}$  $\text{f(x).}$', '["$2$", "$3$", "$0$", "$4$"]'::jsonb, 1, '$\text{At}$ $x=3$ $\text{and}$ $\text{just}$ $\text{above}$ $\text{it,}$ $\text{on}$ $\text{the}$ $\text{interval}$ $[3, 4)$$\text{,}$ $\text{the}$ $\text{greatest}$ $\text{integer}$ $\text{function}$ $[x]$ $\text{equals}$ $3$$\text{.}$ $\text{So}$ $\text{the}$ $\text{right-hand}$ $\text{limit}$ $\text{is}$ $\lim_{x \to 3^+} [x] = 3$$\text{.}$', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 0} [\sin(4x)/x]$$\text{.}$', '["$4$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$", "$1$", "$0$"]'::jsonb, 0, '$\text{Rewrite}$ $\dfrac{\sin(4x)}{x}$ $\text{as}$ $4 \cdot \dfrac{\sin(4x)}{4x}$$\text{.}$ $\text{Using}$ $\lim_{x \to 0} \dfrac{\sin(kx)}{kx} = 1$ $\text{with}$ $k=4$$\text{,}$ $\text{the}$ $\text{second}$ $\text{factor}$ $\text{tends}$ $\text{to}$ $1$$\text{,}$ $\text{leaving}$ $\lim_{x \to 0} \dfrac{\sin(4x)}{x}$ = $4 \cdot 1$ = $4$$\text{.}$', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 0} [\sin(3x)/(5x)]$$\text{.}$', '["$3/5$", "$1$", "$0$", "$5/3$"]'::jsonb, 0, '$\text{Rewrite}$ $\dfrac{\sin(3x)}{5x}$ $\text{as}$ $\frac{3}{5} \cdot \dfrac{\sin(3x)}{3x}$$\text{.}$ $\text{Using}$ $\lim_{x \to 0} \dfrac{\sin(kx)}{kx} = 1$ $\text{with}$ $k=3$$\text{,}$ $\text{the}$ $\text{second}$ $\text{factor}$ $\text{tends}$ $\text{to}$ $1$$\text{,}$ $\text{leaving}$ $\lim_{x \to 0} \dfrac{\sin(3x)}{5x}$ = $\frac{3}{5} \cdot 1$ = $\frac{3}{5}$$\text{.}$', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 0} [(1-cos x)/x]$$\text{.}$', '["$1$", "$0$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$", "$1/2$"]'::jsonb, 1, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{limit}$ $\lim_{x \to 0} \dfrac{\cos(x) - 1}{x}$ = $0$ $\text{(equivalently}$ $\lim_{x \to 0} \dfrac{1 - \cos(x)}{x}$ = $0$$\text{,}$ $\text{since}$ $1-\cos x$ $\text{is}$ $\text{a}$ $\text{sign}$ $\text{flip}$ $\text{of}$ $\cos x - 1$$\text{):}$ $\lim_{x \to 0} \frac{1 - \cos{\left(x \right)}}{x}$ = $0$$\text{.}$', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\lim_{x \to 0} [x \cdot \sin(1/x)]$ $\text{using}$ $\text{the}$ $\text{Sandwich}$ $\text{Theorem.}$', '["$0$", "$1$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$", "$\\infty$"]'::jsonb, 0, '$-1 \leq \sin(1/x) \leq 1$ $\text{for}$ $\text{every}$ $x \neq 0$$\text{,}$ $\text{so}$ $\text{multiplying}$ $\text{through}$ $\text{by}$ $|x|$ $\text{gives}$ $-|x| \leq x\sin(1/x) \leq |x|$$\text{.}$ $\text{As}$ $x \to 0$$\text{,}$ $\text{both}$ $\text{bounds}$ $-|x|$ $\text{and}$ $|x|$ $\text{tend}$ $\text{to}$ $0$$\text{,}$ $\text{so}$ $\text{by}$ $\text{the}$ $\text{Sandwich}$ $\text{(Squeeze)}$ $\text{Theorem,}$ $\lim_{x \to 0} x\sin(1/x) = 0$$\text{.}$', 'Some Theorems on Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = (x^2-25)/(x-5)$ $\text{if}$ $x \neq 5$$\text{,}$ $\text{and}$ $f(5)$$=10$$\text{,}$ $\text{is}$ $\text{f}$ $\text{continuous}$ $\text{at}$ $\text{x=5?}$', '["$\\text{No}$ $\\text{—}$ $\\text{removable}$ $\\text{discontinuity}$", "$\\text{No}$ $\\text{—}$ $\\text{jump}$ $\\text{discontinuity}$", "$\\text{No}$ $\\text{—}$ $\\text{essential}$ $\\text{discontinuity}$", "$\\text{Yes}$ $\\text{—}$ $\\text{f}$ $\\text{is}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=5}$"]'::jsonb, 3, '$\text{Simplify:}$ $\frac{x^{2} - 25}{x - 5} = x + 5$ $\text{for}$ $x \neq 5$$\text{,}$ $\text{so}$ $\lim_{x \to 5} f(x) = 5 + 5 = 10$$\text{.}$ $\text{This}$ $\text{equals}$ $\text{the}$ $\text{given}$ $f(5) = 10$$\text{,}$ $\text{and}$ $\text{since}$ $\text{the}$ $\text{limit}$ $\text{exists}$ $\text{and}$ $\text{matches}$ $f(5)$$\text{,}$ $f$ $\text{is}$ $\text{continuous}$ $\text{at}$ $x=5$$\text{.}$', 'Continuous Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = (x^2-25)/(x-5)$ $\text{if}$ $x \neq 5$$\text{,}$ $\text{and}$ $f(5)$$=7$$\text{,}$ $\text{is}$ $\text{f}$ $\text{continuous}$ $\text{at}$ $\text{x=5?}$', '["$\\text{No}$ $\\text{—}$ $\\text{essential}$ $\\text{discontinuity}$", "$\\text{Yes}$ $\\text{—}$ $\\text{f}$ $\\text{is}$ $\\text{continuous}$ $\\text{at}$ $\\text{x=5}$", "$\\text{No}$ $\\text{—}$ $\\text{removable}$ $\\text{discontinuity}$", "$\\text{No}$ $\\text{—}$ $\\text{jump}$ $\\text{discontinuity}$"]'::jsonb, 2, '$\text{Simplify:}$ $\frac{x^{2} - 25}{x - 5} = x + 5$ $\text{for}$ $x \neq 5$$\text{,}$ $\text{so}$ $\lim_{x \to 5} f(x) = 5 + 5 = 10$$\text{,}$ $\text{but}$ $\text{the}$ $\text{given}$ $f(5) = 7 \neq 10$$\text{.}$ $\text{The}$ $\text{limit}$ $\text{exists}$ $\text{but}$ $\text{does}$ $\text{not}$ $\text{equal}$ $f(5)$$\text{,}$ $\text{so}$ $f$ $\text{is}$ $\text{discontinuous}$ $\text{at}$ $x=5$$\text{.}$', 'Types of Discontinuities', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = x^5$$\text{.}$', '["$5x^5$", "$5x^4$", "$20x^3$", "$x^5$"]'::jsonb, 1, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[x^{5}] = 5 x^{4} = 5 x^{4}$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 5 x^{4}$$\text{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = 3x^4$$\text{.}$', '["$12x^3$", "$3x^4$", "$12x^4$", "$36x^2$"]'::jsonb, 0, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[3 \cdot x^{4}]$ = $3 \cdot 4 x^{3}$ = $12 x^{3}$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 12 x^{3}$$\text{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = 7x^3 - 2x^2 + x$$\text{.}$', '["$7x^3 - 2x^2 + x$", "$21x^3 - 4x^2 + x$", "$42x - 4$", "$21x^2 - 4x + 1$"]'::jsonb, 3, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[7 \cdot x^{3}]$ = $7 \cdot 3 x^{2}$ = $21 x^{2}$$\text{;}$ $\dfrac{d}{dx}[-2 \cdot x^{2}]$ = $-2 \cdot 2 x^{1}$ = $- 4 x$$\text{;}$ $\dfrac{d}{dx}[x^{1}] = 1 x^{0} = 1$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 21 x^{2} - 4 x + 1$$\text{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = x^6 - 4x$$\text{.}$', '["$30x^4$", "$6x^5 - 4$", "$x^6 - 4x$", "$6x^6 - 4x$"]'::jsonb, 1, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[x^{6}] = 6 x^{5} = 6 x^{5}$$\text{;}$ $\dfrac{d}{dx}[-4 \cdot x^{1}]$ = $-4 \cdot 1 x^{0}$ = $-4$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 6 x^{5} - 4$$\text{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = 2x^7 + 5$$\text{.}$', '["$14x^6$", "$14x^7$", "$84x^5$", "$2x^7 + 5$"]'::jsonb, 0, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[2 \cdot x^{7}]$ = $2 \cdot 7 x^{6}$ = $14 x^{6}$$\text{;}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $\text{the}$ $\text{constant}$ $5$ $\text{is}$ $0$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 14 x^{6}$$\text{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = x^2/2 - 3x$$\text{.}$', '["$1$", "$x - 3$", "$x^2/2 - 3x$", "$x^2 - 3x$"]'::jsonb, 1, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[\frac{1}{2} \cdot x^{2}]$ = $\frac{1}{2} \cdot 2 x^{1}$ = $x$$\text{;}$ $\dfrac{d}{dx}[-3 \cdot x^{1}]$ = $-3 \cdot 1 x^{0}$ = $-3$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = x - 3$$\text{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \sin(x)$$\text{.}$', '["$\\cos(x) + 1$", "$\\cos(x)$", "$\\sin(x)$", "$-\\cos(x)$"]'::jsonb, 1, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[\sin(x)] = \cos(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = \cos{\left(x \right)}$$\text{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \cos(x)$$\text{.}$', '["$\\sin(x)$", "$-\\sin(x)$", "$\\cos(x)$", "$1 - \\sin(x)$"]'::jsonb, 1, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[\cos(x)] = -\sin(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = - \sin{\left(x \right)}$$\text{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \tan(x)$$\text{.}$', '["$-1/\\cos(x)^2$", "$\\tan(x)$", "$\\cos(x)$", "$\\cos(x)^{-2}$"]'::jsonb, 3, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[\tan{\left(x \right)}]$ = $\tan^{2}{\left(x \right)} + 1$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 1 + \tan^{2}{\left(x \right)}$$\text{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = 3 \sin(x)$$\text{.}$', '["$\\cos(x)$", "$-3 \\cos(x)$", "$3 \\cos(x)$", "$3 \\sin(x)$"]'::jsonb, 2, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[3 \cdot \sin(x)]$ = $3 \cdot \cos(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x) = 3 \cos{\left(x \right)}$$\text{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \sin(x) + \cos(x)$$\text{.}$', '["$-\\sin(x) + \\cos(x)$", "$\\sin(x) - \\cos(x)$", "$\\sin(x) + \\cos(x)$", "$\\cos(x)$"]'::jsonb, 0, '$\text{Differentiate}$ $\text{term}$ $\text{by}$ $\text{term:}$ $\dfrac{d}{dx}[\sin(x)] = \cos(x)$$\text{;}$ $\dfrac{d}{dx}[\cos(x)] = -\sin(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms:}$ $f''(x)$ = $\cos{\left(x \right)}$ - $\sin{\left(x \right)}$$\text{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Product}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = x^2 \cdot \sin(x)$$\text{.}$', '["$x(x \\cos(x) + 2 \\sin(x))$", "$x^2 \\cos(x)$", "$2x \\cos(x)$", "$2x \\sin(x)$"]'::jsonb, 0, '$\text{Product}$ $\text{Rule:}$ $(uv)'' = u''v + uv''$$\text{.}$ $\text{With}$ $u = x^{2}$ $\text{and}$ $v = \sin{\left(x \right)}$$\text{:}$ $u'' = 2 x$ $\text{and}$ $v'' = \cos{\left(x \right)}$$\text{.}$ $\text{So}$ $f''(x)$ = $u''v + uv''$ = $(2 x)(\sin{\left(x \right)})$ + $(x^{2})(\cos{\left(x \right)})$ = $x \left(x \cos{\left(x \right)} + 2 \sin{\left(x \right)}\right)$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Product}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = x \cdot \cos(x)$$\text{.}$', '["$-x \\sin(x)$", "$-x \\sin(x) + \\cos(x)$", "$\\cos(x)$", "$-\\sin(x)$"]'::jsonb, 1, '$\text{Product}$ $\text{Rule:}$ $(uv)'' = u''v + uv''$$\text{.}$ $\text{With}$ $u = x$ $\text{and}$ $v = \cos{\left(x \right)}$$\text{:}$ $u'' = 1$ $\text{and}$ $v'' = - \sin{\left(x \right)}$$\text{.}$ $\text{So}$ $f''(x)$ = $u''v + uv''$ = $(1)(\cos{\left(x \right)})$ + $(x)(- \sin{\left(x \right)})$ = $- x \sin{\left(x \right)}$ + $\cos{\left(x \right)}$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Product}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = x^2 \cdot x + 1$$\text{.}$', '["$x^2$", "$2x$", "$2x^2 + 2x$", "$3x^2 + 2x$"]'::jsonb, 3, '$\text{Product}$ $\text{Rule:}$ $(uv)'' = u''v + uv''$$\text{.}$ $\text{With}$ $u = x^{2}$ $\text{and}$ $v = x + 1$$\text{:}$ $u'' = 2 x$ $\text{and}$ $v'' = 1$$\text{.}$ $\text{So}$ $f''(x)$ = $u''v + uv''$ = $(2 x)(x + 1) + (x^{2})(1)$ = $x \left(3 x + 2\right)$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Product}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \sin(x) \cdot \cos(x)$$\text{.}$', '["$\\cos(2x)$", "$-\\sin(x)^2$", "$\\cos(x)^2$", "$-\\sin(2x)/2$"]'::jsonb, 0, '$\text{Product}$ $\text{Rule:}$ $(uv)'' = u''v + uv''$$\text{.}$ $\text{With}$ $u = \sin{\left(x \right)}$ $\text{and}$ $v = \cos{\left(x \right)}$$\text{:}$ $u'' = \cos{\left(x \right)}$ $\text{and}$ $v'' = - \sin{\left(x \right)}$$\text{.}$ $\text{So}$ $f''(x)$ = $u''v + uv''$ = $(\cos{\left(x \right)})(\cos{\left(x \right)})$ + $(\sin{\left(x \right)})(- \sin{\left(x \right)})$ = $\cos{\left(2 x \right)}$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Quotient}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (x)/(x + 1)$$\text{.}$', '["$1/(x^2 + 2x + 1)$", "$1/(x + 1)$", "$1$", "$2x/(x^2 + 2x + 1) + 1/(x^2 + 2x + 1)$"]'::jsonb, 0, '$\text{Quotient}$ $\text{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\text{.}$ $\text{With}$ $u = x$ $\text{and}$ $v = x + 1$$\text{:}$ $u'' = 1$ $\text{and}$ $v'' = 1$$\text{.}$ $\text{So}$ $f''(x)$ = $\dfrac{u''v - uv''}{v^2}$ = $\dfrac{(1)(x + 1) - (x)(1)}{(x + 1)^2}$ = $\dfrac{1}{x^{2} + 2 x + 1}$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Quotient}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (x^2)/(x - 2)$$\text{.}$', '["$x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$", "$2x$", "$2x/(x - 2)$", "$3x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$"]'::jsonb, 0, '$\text{Quotient}$ $\text{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\text{.}$ $\text{With}$ $u = x^{2}$ $\text{and}$ $v = x - 2$$\text{:}$ $u'' = 2 x$ $\text{and}$ $v'' = 1$$\text{.}$ $\text{So}$ $f''(x)$ = $\dfrac{u''v - uv''}{v^2}$ = $\dfrac{(2 x)(x - 2) - (x^{2})(1)}{(x - 2)^2}$ = $\dfrac{x^{2} - 4 x}{x^{2} - 4 x + 4}$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Quotient}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (\sin(x))/(x)$$\text{.}$', '["$(x \\cos(x) + \\sin(x))/x^2$", "$(x \\cos(x) - \\sin(x))/x^2$", "$\\cos(x)/x$", "$\\cos(x)$"]'::jsonb, 1, '$\text{Quotient}$ $\text{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\text{.}$ $\text{With}$ $u = \sin{\left(x \right)}$ $\text{and}$ $v = x$$\text{:}$ $u'' = \cos{\left(x \right)}$ $\text{and}$ $v'' = 1$$\text{.}$ $\text{So}$ $f''(x)$ = $\dfrac{u''v - uv''}{v^2}$ = $\dfrac{(\cos{\left(x \right)})(x) - (\sin{\left(x \right)})(1)}{(x)^2}$ = $\dfrac{x \cos{\left(x \right)} - \sin{\left(x \right)}}{x^{2}}$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Quotient}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (2x + 1)/(x^2 + 1)$$\text{.}$', '["$1/x$", "$-2x^2/(x^4 + 2x^2 + 1)$ - $2x/(x^4 + 2x^2 + 1)$ + $2/(x^4 + 2x^2 + 1)$", "$2/(x^2 + 1)$", "$6x^2/(x^4 + 2x^2 + 1)$ + $2x/(x^4 + 2x^2 + 1)$ + $2/(x^4 + 2x^2 + 1)$"]'::jsonb, 1, '$\text{Quotient}$ $\text{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\text{.}$ $\text{With}$ $u = 2 x + 1$ $\text{and}$ $v = x^{2} + 1$$\text{:}$ $u'' = 2$ $\text{and}$ $v'' = 2 x$$\text{.}$ $\text{So}$ $f''(x)$ = $\dfrac{u''v - uv''}{v^2}$ = $\dfrac{(2)(x^{2} + 1) - (2 x + 1)(2 x)}{(x^{2} + 1)^2}$ = $\dfrac{- 2 x^{2} - 2 x + 2}{x^{4} + 2 x^{2} + 1}$$\text{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (x^2 + 1)^3$$\text{.}$', '["$3x^4 + 6x^2 + 3$", "$6x^5 + 12x^3 + 6x$", "$8x^3$", "$6x^7 + 18x^5 + 18x^3 + 6x$"]'::jsonb, 1, '$\text{Chain}$ $\text{Rule:}$ $\text{with}$ $u = x^{2} + 1$$\text{,}$ $\dfrac{d}{dx}[u^{3}] = 3 u^{2} \cdot u''$$\text{.}$ $\text{Here}$ $u'' = 2 x$$\text{,}$ $\text{so}$ $f''(x)$ = $3(x^{2} + 1)^{2} \cdot (2 x)$ = $6 x^{5} + 12 x^{3} + 6 x$$\text{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (2x - 5)^4$$\text{.}$', '["$64x^3 - 480x^2 + 1200x - 1000$", "$16$", "$128x^4$ - $1280x^3$ + $4800x^2$ - $8000x$ + $5000$", "$32x^3 - 240x^2 + 600x - 500$"]'::jsonb, 0, '$\text{Chain}$ $\text{Rule:}$ $\text{with}$ $u = 2 x - 5$$\text{,}$ $\dfrac{d}{dx}[u^{4}] = 4 u^{3} \cdot u''$$\text{.}$ $\text{Here}$ $u'' = 2$$\text{,}$ $\text{so}$ $f''(x)$ = $4(2 x - 5)^{3} \cdot (2)$ = $64 x^{3} - 480 x^{2} + 1200 x - 1000$$\text{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\text{find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = (x^3 - 2x)^2$$\text{.}$', '["$2x^3 - 4x$", "$9x^4 - 12x^2 + 4$", "$6x^5 - 16x^3 + 8x$", "$6x^8 - 28x^6 + 40x^4 - 16x^2$"]'::jsonb, 2, '$\text{Chain}$ $\text{Rule:}$ $\text{with}$ $u = x^{3} - 2 x$$\text{,}$ $\dfrac{d}{dx}[u^{2}] = 2 u^{1} \cdot u''$$\text{.}$ $\text{Here}$ $u'' = 3 x^{2} - 2$$\text{,}$ $\text{so}$ $f''(x)$ = $2(x^{3} - 2 x)^{1} \cdot (3 x^{2} - 2)$ = $6 x^{5} - 16 x^{3} + 8 x$$\text{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \sin(2x + 3)$$\text{.}$', '["$2 \\cos(2x + 3)$", "$\\cos(2x + 3)$", "$-2 \\cos(2x + 3)$", "$\\sin(2)$"]'::jsonb, 0, '$\text{Chain}$ $\text{Rule:}$ $\text{with}$ $u = 2 x + 3$$\text{,}$ $\dfrac{d}{dx}[\sin(u)]$ = $\cos(u) \cdot u''$$\text{.}$ $\text{Here}$ $u'' = 2$$\text{,}$ $\text{so}$ $f''(x)$ = $\cos(2 x + 3) \cdot (2)$ = $2 \cos{\left(2 x + 3 \right)}$$\text{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \sin(x^2)$$\text{.}$', '["$-2x \\cos(x^2)$", "$\\sin(2x)$", "$\\cos(x^2)$", "$2x \\cos(x^2)$"]'::jsonb, 3, '$\text{Chain}$ $\text{Rule:}$ $\text{with}$ $u = x^{2}$$\text{,}$ $\dfrac{d}{dx}[\sin(u)]$ = $\cos(u) \cdot u''$$\text{.}$ $\text{Here}$ $u'' = 2 x$$\text{,}$ $\text{so}$ $f''(x)$ = $\cos(x^{2}) \cdot (2 x)$ = $2 x \cos{\left(x^{2} \right)}$$\text{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \sin(3x - 1)$$\text{.}$', '["$\\cos(3x - 1)$", "$-3 \\cos(3x - 1)$", "$3 \\cos(3x - 1)$", "$\\sin(3)$"]'::jsonb, 2, '$\text{Chain}$ $\text{Rule:}$ $\text{with}$ $u = 3 x - 1$$\text{,}$ $\dfrac{d}{dx}[\sin(u)]$ = $\cos(u) \cdot u''$$\text{.}$ $\text{Here}$ $u'' = 3$$\text{,}$ $\text{so}$ $f''(x)$ = $\cos(3 x - 1) \cdot (3)$ = $3 \cos{\left(3 x - 1 \right)}$$\text{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^2 - 4x + 3 at x = 1$$\text{.}$', '["$-2$", "$-1$", "$0$", "$2$"]'::jsonb, 0, '$\text{The}$ $\text{slope}$ $\text{is}$ $f''(1)$ $\text{where}$ $f''(x) = 2 x - 4$$\text{,}$ $\text{so}$ $f''(1) = 2 \cdot 1 - 4 = -2$$\text{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^3 - 3x at x = 2$$\text{.}$', '["$2$", "$11$", "$-9$", "$9$"]'::jsonb, 3, '$\text{The}$ $\text{slope}$ $\text{is}$ $f''(2)$ $\text{where}$ $f''(x) = 3 x^{2} - 3$$\text{,}$ $\text{so}$ $f''(2) = 3 \cdot 2^{2} - 3 = 9$$\text{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = 2x^2 + 1 at x = -1$$\text{.}$', '["$-4$", "$3$", "$-2$", "$4$"]'::jsonb, 0, '$\text{The}$ $\text{slope}$ $\text{is}$ $f''(-1)$ $\text{where}$ $f''(x) = 4 x$$\text{,}$ $\text{so}$ $f''(-1) = 4 \left(-1\right) = -4$$\text{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{slope}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^2 at x = 3$$\text{.}$', '["$9$", "$6$", "$-6$", "$8$"]'::jsonb, 1, '$\text{The}$ $\text{slope}$ $\text{is}$ $f''(3)$ $\text{where}$ $f''(x) = 2 x$$\text{,}$ $\text{so}$ $f''(3) = 2 \cdot 3 = 6$$\text{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $\text{x²}$ $\text{+}$ $\text{y²}$ $\text{=}$ $\text{25,}$ $\text{find}$ $\text{dy/dx}$ $\text{at}$ $\text{the}$ $\text{point}$ $\text{(3,4).}$', '["$4/3$", "$-4/3$", "$3/4$", "$-3/4$"]'::jsonb, 3, '$\text{Differentiate}$ $\text{both}$ $\text{sides}$ $\text{of}$ $x^{2} + y^{2} = 25$ $\text{implicitly}$ $\text{with}$ $\text{respect}$ $\text{to}$ $x$$\text{,}$ $\text{treating}$ $y$ $\text{as}$ $\text{a}$ $\text{function}$ $\text{of}$ $x$$\text{:}$ $2 x + 2 y(dy/dx) = 0$$\text{.}$ $\text{Solving}$ $\text{for}$ $dy/dx$$\text{:}$ $dy/dx = - \frac{x}{y}$$\text{.}$ $\text{At}$ $(3,4)$$\text{:}$ $dy/dx = - \frac{3}{4} = - \frac{3}{4}$$\text{.}$', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $\text{x³}$ $\text{+}$ $\text{y³}$ $\text{=}$ $\text{9,}$ $\text{find}$ $\text{dy/dx}$ $\text{at}$ $\text{the}$ $\text{point}$ $\text{(1,2).}$', '["$1/4$", "$-4$", "$4$", "$-1/4$"]'::jsonb, 3, '$\text{Differentiate}$ $\text{both}$ $\text{sides}$ $\text{of}$ $x^{3} + y^{3} = 9$ $\text{implicitly}$ $\text{with}$ $\text{respect}$ $\text{to}$ $x$$\text{,}$ $\text{treating}$ $y$ $\text{as}$ $\text{a}$ $\text{function}$ $\text{of}$ $x$$\text{:}$ $3 x^{2} + 3 y^{2}(dy/dx) = 0$$\text{.}$ $\text{Solving}$ $\text{for}$ $dy/dx$$\text{:}$ $dy/dx = - \frac{x^{2}}{y^{2}}$$\text{.}$ $\text{At}$ $(1,2)$$\text{:}$ $dy/dx = - \frac{1}{4} = - \frac{1}{4}$$\text{.}$', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{critical}$ $\text{point(s)}$ $\text{of}$ $f(x) = x^3 - 3x + 1$$\text{.}$', '["$0$", "$-1, 1$", "$\\text{no}$ $\\text{critical}$ $\\text{points}$", "$0, 2$"]'::jsonb, 1, '$f''(x) = 3 x^{2} - 3$$\text{.}$ $\text{Setting}$ $f''(x) = 0$$\text{:}$ $3 x^{2} - 3 = 0$$\text{,}$ $\text{which}$ $\text{gives}$ $x = -1, 1$$\text{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{critical}$ $\text{point(s)}$ $\text{of}$ $f(x) = x^2 - 6x + 5$$\text{.}$', '["$\\text{no}$ $\\text{critical}$ $\\text{points}$", "$3$", "$4$", "$2$"]'::jsonb, 1, '$f''(x) = 2 x - 6$$\text{.}$ $\text{Setting}$ $f''(x) = 0$$\text{:}$ $2 x - 6 = 0$$\text{,}$ $\text{which}$ $\text{gives}$ $x = 3$$\text{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{critical}$ $\text{point(s)}$ $\text{of}$ $f(x) = 2x^3 - 3x^2 - 12x + 4$$\text{.}$', '["$0, 3$", "$0$", "$\\text{no}$ $\\text{critical}$ $\\text{points}$", "$-1, 2$"]'::jsonb, 3, '$f''(x) = 6 x^{2} - 6 x - 12$$\text{.}$ $\text{Setting}$ $f''(x) = 0$$\text{:}$ $6 x^{2} - 6 x - 12 = 0$$\text{,}$ $\text{which}$ $\text{gives}$ $x = -1, 2$$\text{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{critical}$ $\text{point(s)}$ $\text{of}$ $f(x) = x^3 - 12x$$\text{.}$', '["$-2, 2$", "$-1, 3$", "$0$", "$\\text{no}$ $\\text{critical}$ $\\text{points}$"]'::jsonb, 0, '$f''(x) = 3 x^{2} - 12$$\text{.}$ $\text{Setting}$ $f''(x) = 0$$\text{:}$ $3 x^{2} - 12 = 0$$\text{,}$ $\text{which}$ $\text{gives}$ $x = -2, 2$$\text{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{At}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{x}$ $\text{=}$ $\text{1}$ $\text{of}$ $f(x) = x^3 - 3x$$\text{,}$ $\text{the}$ $\text{Second}$ $\text{Derivative}$ $\text{Test}$ $\text{shows}$ $\text{this}$ $\text{is}$ $\text{a:}$', '["$\\text{point}$ $\\text{of}$ $\\text{inflection}$", "$\\text{relative}$ $\\text{maximum}$", "$\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$", "$\\text{relative}$ $\\text{minimum}$"]'::jsonb, 3, '$f''''(x) = 6 x$$\text{,}$ $\text{so}$ $f''''(1) = 6 \cdot 1 = 6$$\text{,}$ $\text{which}$ $\text{is}$ $\text{positive,}$ $\text{indicating}$ $\text{a}$ $\text{relative}$ $\text{minimum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{At}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{x}$ $\text{=}$ $\text{-1}$ $\text{of}$ $f(x) = x^3 - 3x$$\text{,}$ $\text{the}$ $\text{Second}$ $\text{Derivative}$ $\text{Test}$ $\text{shows}$ $\text{this}$ $\text{is}$ $\text{a:}$', '["$\\text{relative}$ $\\text{minimum}$", "$\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$", "$\\text{relative}$ $\\text{maximum}$", "$\\text{point}$ $\\text{of}$ $\\text{inflection}$"]'::jsonb, 2, '$f''''(x) = 6 x$$\text{,}$ $\text{so}$ $f''''(-1) = 6 \left(-1\right) = -6$$\text{,}$ $\text{which}$ $\text{is}$ $\text{negative,}$ $\text{indicating}$ $\text{a}$ $\text{relative}$ $\text{maximum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{At}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{x}$ $\text{=}$ $\text{2}$ $\text{of}$ $f(x) = x^2 - 4x + 7$$\text{,}$ $\text{the}$ $\text{Second}$ $\text{Derivative}$ $\text{Test}$ $\text{shows}$ $\text{this}$ $\text{is}$ $\text{a:}$', '["$\\text{relative}$ $\\text{maximum}$", "$\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$", "$\\text{relative}$ $\\text{minimum}$", "$\\text{point}$ $\\text{of}$ $\\text{inflection}$"]'::jsonb, 2, '$f''''(x) = 2$$\text{,}$ $\text{so}$ $f''''(2) = 2 = 2$$\text{,}$ $\text{which}$ $\text{is}$ $\text{positive,}$ $\text{indicating}$ $\text{a}$ $\text{relative}$ $\text{minimum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{At}$ $\text{the}$ $\text{critical}$ $\text{point}$ $\text{x}$ $\text{=}$ $\text{3}$ $\text{of}$ $f(x) = -x^2 + 6x - 5$$\text{,}$ $\text{the}$ $\text{Second}$ $\text{Derivative}$ $\text{Test}$ $\text{shows}$ $\text{this}$ $\text{is}$ $\text{a:}$', '["$\\text{not}$ $\\text{a}$ $\\text{critical}$ $\\text{point}$", "$\\text{relative}$ $\\text{maximum}$", "$\\text{relative}$ $\\text{minimum}$", "$\\text{point}$ $\\text{of}$ $\\text{inflection}$"]'::jsonb, 1, '$f''''(x) = -2$$\text{,}$ $\text{so}$ $f''''(3) = -2 = -2$$\text{,}$ $\text{which}$ $\text{is}$ $\text{negative,}$ $\text{indicating}$ $\text{a}$ $\text{relative}$ $\text{maximum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^2 - 4x + 3$$\text{,}$ $\text{on}$ $\text{which}$ $\text{interval}$ $\text{is}$ $\text{f}$ $\text{increasing?}$', '["$(2, \\infty)$", "$(-\\infty, \\infty)$", "$(0, 2)$", "$(-\\infty, 2)$"]'::jsonb, 0, '$f''(x) = 2 \left(x - 2\right)$$\text{.}$ $\text{Solving}$ $f''(x) > 0$ $\text{shows}$ $f''(x)$ $\text{is}$ $\text{positive}$ $\text{for}$ $x \in \left(2, \infty\right)$$\text{,}$ $\text{so}$ $f$ $\text{is}$ $\text{increasing}$ $\text{on}$ $\left(2, \infty\right)$$\text{.}$', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^3 - 3x$$\text{,}$ $\text{on}$ $\text{which}$ $\text{interval}$ $\text{is}$ $\text{f}$ $\text{decreasing?}$', '["$(-\\infty, \\infty)$", "$(-\\infty,-1)$", "$(-1, 1)$", "$(1, \\infty)$"]'::jsonb, 2, '$f''(x)$ = $3 \left(x - 1\right) \left(x + 1\right)$$\text{.}$ $\text{Solving}$ $f''(x) < 0$ $\text{shows}$ $f''(x)$ $\text{is}$ $\text{negative}$ $\text{for}$ $x \in \left(-1, 1\right)$$\text{,}$ $\text{so}$ $f$ $\text{is}$ $\text{decreasing}$ $\text{on}$ $\left(-1, 1\right)$$\text{.}$', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^2 at x = -1$$\text{.}$', '["$y = -2x + 1$", "$y = -2x - 1$", "$y = 1x - 2$", "$y = 2x - 1$"]'::jsonb, 1, '$f(-1) = 1$$\text{,}$ $f''(-1) = -2$$\text{.}$ $\text{Using}$ $\text{the}$ $\text{point-slope}$ $\text{form}$ $y - f(a) = f''(a)(x-a)$$\text{:}$ $y - 1 = -2(x - -1)$$\text{,}$ $\text{which}$ $\text{simplifies}$ $\text{to}$ $y = -2x - 1$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^2 - 3x + 2 at x = 1$$\text{.}$', '["$y = 0x - 1$", "$y = 1x + 1$", "$y = -1x + 1$", "$y = -1x$"]'::jsonb, 2, '$f(1) = 0$$\text{,}$ $f''(1) = -1$$\text{.}$ $\text{Using}$ $\text{the}$ $\text{point-slope}$ $\text{form}$ $y - f(a) = f''(a)(x-a)$$\text{:}$ $y - 0 = -1(x - 1)$$\text{,}$ $\text{which}$ $\text{simplifies}$ $\text{to}$ $y = -1x + 1$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^3 at x = 1$$\text{.}$', '["$y = -3x - 2$", "$y = 3x + 1$", "$y = 3x - 2$", "$y = 1x + 3$"]'::jsonb, 2, '$f(1) = 1$$\text{,}$ $f''(1) = 3$$\text{.}$ $\text{Using}$ $\text{the}$ $\text{point-slope}$ $\text{form}$ $y - f(a) = f''(a)(x-a)$$\text{:}$ $y - 1 = 3(x - 1)$$\text{,}$ $\text{which}$ $\text{simplifies}$ $\text{to}$ $y = 3x - 2$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{equation}$ $\text{of}$ $\text{the}$ $\text{tangent}$ $\text{line}$ $\text{to}$ $y = x^2 at x = 3$$\text{.}$', '["$y = -6x - 9$", "$y = 9x + 6$", "$y = 6x + 9$", "$y = 6x - 9$"]'::jsonb, 3, '$f(3) = 9$$\text{,}$ $f''(3) = 6$$\text{.}$ $\text{Using}$ $\text{the}$ $\text{point-slope}$ $\text{form}$ $y - f(a) = f''(a)(x-a)$$\text{:}$ $y - 9 = 6(x - 3)$$\text{,}$ $\text{which}$ $\text{simplifies}$ $\text{to}$ $y = 6x - 9$$\text{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{L''Hopital''s}$ $\text{Rule}$ $\text{to}$ $\text{evaluate}$ $\lim_{x \to 0} [\sin(x)/x]$$\text{.}$', '["$1$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$", "$\\infty$", "$0$"]'::jsonb, 0, '$\text{This}$ $\text{is}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Differentiate}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{separately:}$ $\dfrac{d}{dx}[\sin{\left(x \right)}]$ = $\cos{\left(x \right)}$ $\text{and}$ $\dfrac{d}{dx}[x] = 1$$\text{.}$ $\text{By}$ $\text{L''Hopital''s}$ $\text{Rule,}$ $\lim_{x \to 0} \frac{\sin{\left(x \right)}}{x}$ = $\lim_{x \to 0} \dfrac{\cos{\left(x \right)}}{1}$ = $\cos{\left(0 \right)}$ = $1$$\text{.}$', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{L''Hopital''s}$ $\text{Rule}$ $\text{to}$ $\text{evaluate}$ $\lim_{x \to 1} [(x^2 - 1)/(x - 1)]$$\text{.}$', '["$2$", "$\\infty$", "$0$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$"]'::jsonb, 0, '$\text{This}$ $\text{is}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Differentiate}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{separately:}$ $\dfrac{d}{dx}[x^{2} - 1] = 2 x$ $\text{and}$ $\dfrac{d}{dx}[x - 1] = 1$$\text{.}$ $\text{By}$ $\text{L''Hopital''s}$ $\text{Rule,}$ $\lim_{x \to 1} \frac{x^{2} - 1}{x - 1}$ = $\lim_{x \to 1} \dfrac{2 x}{1}$ = $2 \cdot 1$ = $2$$\text{.}$', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{L''Hopital''s}$ $\text{Rule}$ $\text{to}$ $\text{evaluate}$ $\lim_{x \to 0} [(1 - \cos(x))/x^2]$$\text{.}$', '["$\\text{does}$ $\\text{not}$ $\\text{exist}$", "$\\infty$", "$1/2$", "$0$"]'::jsonb, 2, '$\text{This}$ $\text{is}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Differentiate}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{separately:}$ $\dfrac{d}{dx}[1 - \cos{\left(x \right)}]$ = $\sin{\left(x \right)}$ $\text{and}$ $\dfrac{d}{dx}[x^{2}] = 2 x$$\text{.}$ $\text{By}$ $\text{L''Hopital''s}$ $\text{Rule,}$ $\lim_{x \to 0} \frac{1 - \cos{\left(x \right)}}{x^{2}}$ = $\lim_{x \to 0} \dfrac{\sin{\left(x \right)}}{2 x}$ = $\frac{\sin{\left(0 \right)}}{2 \cdot 0}$ = $\frac{1}{2}$$\text{.}$', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Use}$ $\text{L''Hopital''s}$ $\text{Rule}$ $\text{to}$ $\text{evaluate}$ $\lim_{x \to 2} [(x^2 - 4)/(x - 2)]$$\text{.}$', '["$0$", "$\\infty$", "$4$", "$\\text{does}$ $\\text{not}$ $\\text{exist}$"]'::jsonb, 2, '$\text{This}$ $\text{is}$ $\text{a}$ $0/0$ $\text{form.}$ $\text{Differentiate}$ $\text{numerator}$ $\text{and}$ $\text{denominator}$ $\text{separately:}$ $\dfrac{d}{dx}[x^{2} - 4] = 2 x$ $\text{and}$ $\dfrac{d}{dx}[x - 2] = 1$$\text{.}$ $\text{By}$ $\text{L''Hopital''s}$ $\text{Rule,}$ $\lim_{x \to 2} \frac{x^{2} - 4}{x - 2}$ = $\lim_{x \to 2} \dfrac{2 x}{1}$ = $2 \cdot 2$ = $4$$\text{.}$', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^3 - 6x^2 + 9x$$\text{,}$ $\text{find}$ $\text{the}$ $\text{x-coordinate}$ $\text{of}$ $\text{the}$ $\text{point}$ $\text{of}$ $\text{inflection.}$', '["$-2$", "$3$", "$0$", "$2$"]'::jsonb, 3, '$f''''(x) = 6 \left(x - 2\right)$$\text{.}$ $\text{Setting}$ $f''''(x)=0$ $\text{gives}$ $x=2$$\text{,}$ $\text{where}$ $\text{the}$ $\text{sign}$ $\text{of}$ $f''''(x)$ $\text{changes,}$ $\text{so}$ $\text{concavity}$ $\text{changes}$ $\text{there.}$', 'Concavity and Points of Inflection', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{For}$ $f(x) = x^4 - 2x^2$$\text{,}$ $\text{on}$ $\text{which}$ $\text{interval}$ $\text{is}$ $\text{f}$ $\text{concave}$ $\text{up?}$', '["$x < -1/$$\\text{√3}$ $\\text{or}$ $x > 1/$$\\text{√3}$", "$-1/\\sqrt{3} < x < 1/\\sqrt{3}$", "$\\text{all}$ $\\text{real}$ $\\text{x}$", "$\\text{no}$ $\\text{interval}$"]'::jsonb, 0, '$f''''(x) = 4 \left(3 x^{2} - 1\right)$$\text{.}$ $\text{Setting}$ $f''''(x) > 0$ $\text{gives}$ $\left(-\infty, - \frac{\sqrt{3}}{3}\right) \cup \left(\frac{\sqrt{3}}{3}, \infty\right)$$\text{.}$', 'Concavity and Points of Inflection', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 3x^2 \, dx$$\text{.}$', '["$x^3 + C$", "$6x + C$", "$3x^2 + C$", "$2x^3 + C$"]'::jsonb, 0, '$\text{Integrate}$ $\text{term}$ $\text{by}$ $\text{term}$ $\text{using}$ $\text{the}$ $\text{power}$ $\text{rule}$ $\text{for}$ $\text{antiderivatives}$ $\text{(}$$\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$$\text{)}$ $\text{and}$ $\text{the}$ $\text{standard}$ $\text{trigonometric}$ $\text{antiderivatives:}$ $\int 3 \cdot x^{2} \, dx$ = $3 \cdot \dfrac{x^{3}}{3}$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms}$ $\text{and}$ $\text{adding}$ $\text{the}$ $\text{constant}$ $\text{of}$ $\text{integration:}$ $\int f(x) \, dx = x^{3} + C$$\text{.}$', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 4x^3 - 2x \, dx$$\text{.}$', '["$2x^4 - 2x^2 + C$", "$4x^3 - 2x + C$", "$12x^2 - 2 + C$", "$x^4 - x^2 + C$"]'::jsonb, 3, '$\text{Integrate}$ $\text{term}$ $\text{by}$ $\text{term}$ $\text{using}$ $\text{the}$ $\text{power}$ $\text{rule}$ $\text{for}$ $\text{antiderivatives}$ $\text{(}$$\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$$\text{)}$ $\text{and}$ $\text{the}$ $\text{standard}$ $\text{trigonometric}$ $\text{antiderivatives:}$ $\int 4 \cdot x^{3} \, dx$ = $4 \cdot \dfrac{x^{4}}{4}$$\text{;}$ $\int -2 \cdot x^{1} \, dx$ = $-2 \cdot \dfrac{x^{2}}{2}$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms}$ $\text{and}$ $\text{adding}$ $\text{the}$ $\text{constant}$ $\text{of}$ $\text{integration:}$ $\int f(x) \, dx = x^{4} - x^{2} + C$$\text{.}$', 'Antiderivatives of Some Elementary Functions', false),
