  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int \cos(x) \, dx$$\text{.}$', '["$\\cos(x) + C$", "$\\sin(x) + C$", "$-\\sin(x) + C$", "$\\sec(x) + C$"]'::jsonb, 1, '$\text{Integrate}$ $\text{term}$ $\text{by}$ $\text{term}$ $\text{using}$ $\text{the}$ $\text{power}$ $\text{rule}$ $\text{for}$ $\text{antiderivatives}$ $\text{(}$$\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$$\text{)}$ $\text{and}$ $\text{the}$ $\text{standard}$ $\text{trigonometric}$ $\text{antiderivatives:}$ $\int \cos(x) \, dx = \sin(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms}$ $\text{and}$ $\text{adding}$ $\text{the}$ $\text{constant}$ $\text{of}$ $\text{integration:}$ $\int f(x) \, dx$ = $\sin{\left(x \right)} + C$$\text{.}$', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int \sec(x)^2 \, dx$$\text{.}$', '["$\\tan(x) + C$", "$-\\tan(x) + C$", "$\\sec(x)\\tan(x) + C$", "$\\cot(x) + C$"]'::jsonb, 0, '$\text{Integrate}$ $\text{term}$ $\text{by}$ $\text{term}$ $\text{using}$ $\text{the}$ $\text{power}$ $\text{rule}$ $\text{for}$ $\text{antiderivatives}$ $\text{(}$$\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$$\text{)}$ $\text{and}$ $\text{the}$ $\text{standard}$ $\text{trigonometric}$ $\text{antiderivatives:}$ $\int \sec^2(x) \, dx = \tan(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms}$ $\text{and}$ $\text{adding}$ $\text{the}$ $\text{constant}$ $\text{of}$ $\text{integration:}$ $\int f(x) \, dx$ = $\frac{\sin{\left(x \right)}}{\cos{\left(x \right)}}$ + $C$$\text{.}$', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 3 \sin(x) \, dx$$\text{.}$', '["$-3 \\cos(x) + C$", "$\\sec(x) + C$", "$-3 \\sin(x) + C$", "$3 \\cos(x) + C$"]'::jsonb, 0, '$\text{Integrate}$ $\text{term}$ $\text{by}$ $\text{term}$ $\text{using}$ $\text{the}$ $\text{power}$ $\text{rule}$ $\text{for}$ $\text{antiderivatives}$ $\text{(}$$\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$$\text{)}$ $\text{and}$ $\text{the}$ $\text{standard}$ $\text{trigonometric}$ $\text{antiderivatives:}$ $\int 3 \cdot \sin(x) \, dx$ = $3 \cdot -\cos(x)$$\text{.}$ $\text{Summing}$ $\text{the}$ $\text{terms}$ $\text{and}$ $\text{adding}$ $\text{the}$ $\text{constant}$ $\text{of}$ $\text{integration:}$ $\int f(x) \, dx$ = $- 3 \cos{\left(x \right)} + C$$\text{.}$', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{2} x^2 \, dx$$\text{.}$', '["$5/3$", "$-8/3$", "$8/3$", "$11/3$"]'::jsonb, 2, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{3}}{3}$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{0}^{2} x^{2} \, dx$ = $F(2) - F(0)$ = $(\frac{2^{3}}{3} = \frac{8}{3})$ - $(\frac{0^{3}}{3} = 0)$ = $\frac{8}{3} - 0$ = $\frac{8}{3}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{1}^{4} 3x - 1 \, dx$$\text{.}$', '["$41/2$", "$-39/2$", "$20$", "$39/2$"]'::jsonb, 3, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{3 x^{2}}{2} - x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{1}^{4} 3 x - 1 \, dx$ = $F(4) - F(1)$ = $(\frac{4 \left(-2 + 3 \cdot 4\right)}{2}$ = $20)$ - $(\frac{1 \left(-2 + 3 \cdot 1\right)}{2}$ = $\frac{1}{2})$ = $20 - \frac{1}{2}$ = $\frac{39}{2}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{3} x^2 - 4x + 3 \, dx$$\text{.}$', '["$-1$", "$2$", "$0$", "$1$"]'::jsonb, 2, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{3}}{3} - 2 x^{2} + 3 x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{0}^{3} x^{2} - 4 x + 3 \, dx$ = $F(3) - F(0)$ = $(\frac{3 \left(9 - 6 \cdot 3 + 3^{2}\right)}{3}$ = $0)$ - $(\frac{0 \left(9 - 6 \cdot 0 + 0^{2}\right)}{3}$ = $0)$ = $0 - 0$ = $0$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{-1}^{2} 2x + 1 \, dx$$\text{.}$', '["$7$", "$5$", "$6$", "$-6$"]'::jsonb, 2, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = x^{2} + x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{-1}^{2} 2 x + 1 \, dx$ = $F(2) - F(-1)$ = $(2^{2} + 2 = 6)$ - $(\left(-1\right)^{2} + -1 = 0)$ = $6 - 0$ = $6$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{1} x^3 \, dx$$\text{.}$', '["$-3/4$", "$1/4$", "$-1/4$", "$5/4$"]'::jsonb, 1, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{4}}{4}$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{0}^{1} x^{3} \, dx$ = $F(1) - F(0)$ = $(\frac{1^{4}}{4} = \frac{1}{4})$ - $(\frac{0^{4}}{4} = 0)$ = $\frac{1}{4} - 0$ = $\frac{1}{4}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{-1}^{1} 4 - x^2 \, dx$$\text{.}$', '["$-22/3$", "$22/3$", "$25/3$", "$11/3$"]'::jsonb, 1, '$\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = - \frac{x^{3}}{3} + 4 x$$\text{.}$ $\text{By}$ $\text{the}$ $\text{Fundamental}$ $\text{Theorem,}$ $\int_{-1}^{1} 4 - x^{2} \, dx$ = $F(1) - F(-1)$ = $(\frac{1 \left(12 - 1^{2}\right)}{3}$ = $\frac{11}{3})$ - $(\frac{\left(-1\right) \left(12 - \left(-1\right)^{2}\right)}{3}$ = $- \frac{11}{3})$ = $\frac{11}{3} - - \frac{11}{3}$ = $\frac{22}{3}$$\text{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = x^2$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=0$$\text{,}$ $\text{and}$ $\text{x=2.}$', '["$16/3$", "$11/3$", "$-8/3$", "$8/3$"]'::jsonb, 3, '$y=x^{2}$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=0$ $\text{and}$ $x=2$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{0}^{2} x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{3}}{3}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(0)$ = $\frac{2^{3}}{3} - (\frac{0^{3}}{3})$ = $\frac{8}{3}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = 3x$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=0$$\text{,}$ $\text{and}$ $\text{x=4.}$', '["$-24$", "$25$", "$48$", "$24$"]'::jsonb, 3, '$y=3 x$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=0$ $\text{and}$ $x=4$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{0}^{4} 3 x \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{3 x^{2}}{2}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(4) - F(0)$ = $\frac{3 \cdot 4^{2}}{2}$ - $(\frac{3 \cdot 0^{2}}{2})$ = $24$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = 4 - x^2$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=-2$$\text{,}$ $\text{and}$ $\text{x=2.}$', '["$32/3$", "$-32/3$", "$35/3$", "$64/3$"]'::jsonb, 0, '$y=4 - x^{2}$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=-2$ $\text{and}$ $x=2$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-2}^{2} 4 - x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = - \frac{x^{3}}{3} + 4 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(-2)$ = $\frac{2 \left(12 - 2^{2}\right)}{3}$ - $(\frac{\left(-2\right) \left(12 - \left(-2\right)^{2}\right)}{3})$ = $\frac{32}{3}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y = x^3$$\text{,}$ $\text{the}$ $\text{x-axis,}$ $x=0$$\text{,}$ $\text{and}$ $\text{x=2.}$', '["$8$", "$-4$", "$4$", "$5$"]'::jsonb, 2, '$y=x^{3}$ $\text{does}$ $\text{not}$ $\text{cross}$ $\text{the}$ $x$$\text{-axis}$ $\text{between}$ $x=0$ $\text{and}$ $x=2$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{0}^{2} x^{3} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x) = \frac{x^{4}}{4}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(0)$ = $\frac{2^{4}}{4} - (\frac{0^{4}}{4})$ = $4$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y$ = $x + 3 and y$ = $x^2 - 1 between x$ = $-1 and x$ = $1$$\text{.}$', '["$6$", "$-22/3$", "$22/3$", "$28/3$"]'::jsonb, 2, '$\text{Between}$ $x=-1$ $\text{and}$ $x=1$$\text{,}$ $y=x + 3$ $\text{lies}$ $\text{above}$ $y=x^{2} - 1$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-1}^{1} [(x + 3) - (x^{2} - 1)] \, dx$ = $\int_{-1}^{1} - x^{2} + x + 4 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ = $- \frac{x^{3}}{3}$ + $\frac{x^{2}}{2}$ + $4 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(1) - F(-1)$ = $\frac{1 \left(24 + 3 \cdot 1 - 2 \cdot 1^{2}\right)}{6}$ - $(\frac{\left(-1\right) \left(24 + 3 \left(-1\right) - 2 \left(-1\right)^{2}\right)}{6})$ = $\frac{22}{3}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y$ = $6 - x and y$ = $x^2 between x$ = $-3 and x$ = $2$$\text{.}$', '["$65/2$", "$-125/6$", "$137/6$", "$125/6$"]'::jsonb, 3, '$\text{Between}$ $x=-3$ $\text{and}$ $x=2$$\text{,}$ $y=6 - x$ $\text{lies}$ $\text{above}$ $y=x^{2}$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-3}^{2} [(6 - x) - (x^{2})] \, dx$ = $\int_{-3}^{2} - x^{2} - x + 6 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ = $- \frac{x^{3}}{3}$ - $\frac{x^{2}}{2}$ + $6 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(2) - F(-3)$ = $\frac{2 \left(36 - 3 \cdot 2 - 2 \cdot 2^{2}\right)}{6}$ - $(\frac{\left(-3\right) \left(36 - 3 \left(-3\right) - 2 \left(-3\right)^{2}\right)}{6})$ = $\frac{125}{6}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{area}$ $\text{of}$ $\text{the}$ $\text{region}$ $\text{bounded}$ $\text{by}$ $y$ = $x + 5 and y$ = $x^2 - 1 between x$ = $-2 and x$ = $3$$\text{.}$', '["$137/6$", "$55/2$", "$-125/6$", "$125/6$"]'::jsonb, 3, '$\text{Between}$ $x=-2$ $\text{and}$ $x=3$$\text{,}$ $y=x + 5$ $\text{lies}$ $\text{above}$ $y=x^{2} - 1$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $\int_{-2}^{3} [(x + 5) - (x^{2} - 1)] \, dx$ = $\int_{-2}^{3} - x^{2} + x + 6 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ = $- \frac{x^{3}}{3}$ + $\frac{x^{2}}{2}$ + $6 x$$\text{,}$ $\text{so}$ $\text{the}$ $\text{area}$ $\text{is}$ $F(3) - F(-2)$ = $\frac{3 \left(36 + 3 \cdot 3 - 2 \cdot 3^{2}\right)}{6}$ - $(\frac{\left(-2\right) \left(36 + 3 \left(-2\right) - 2 \left(-2\right)^{2}\right)}{6})$ = $\frac{125}{6}$$\text{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = x about the x-axis from x=0 to x=4$$\text{.}$', '["$128\\pi/3$", "$-64\\pi/3$", "$8\\pi$", "$64\\pi/3$"]'::jsonb, 3, '$V$ = $\pi \int_{0}^{4} [x]^2 \, dx$ = $\pi \int_{0}^{4} x^{2} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \frac{x^{3}}{3}$$\text{,}$ $\text{so}$ $V$ = $\pi \left[F(4) - F(0)\right]$ = $\pi \left[\frac{4^{3}}{3} - \left(\frac{0^{3}}{3}\right)\right]$ = $\frac{64 \pi}{3}$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y$ = $sqrt{x} about the x-axis from x$ = $0 to x$ = $4$$\text{.}$', '["$16\\pi$", "$8\\pi$", "$16\\pi/3$", "$-8\\pi$"]'::jsonb, 1, '$V$ = $\pi \int_{0}^{4} [\sqrt{x}]^2 \, dx$ = $\pi \int_{0}^{4} x \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \frac{x^{2}}{2}$$\text{,}$ $\text{so}$ $V$ = $\pi \left[F(4) - F(0)\right]$ = $\pi \left[\frac{4^{2}}{2} - \left(\frac{0^{2}}{2}\right)\right]$ = $8 \pi$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = 2 about the x-axis from x=0 to x=3$$\text{.}$', '["$12\\pi$", "$24\\pi$", "$-12\\pi$", "$6\\pi$"]'::jsonb, 0, '$V$ = $\pi \int_{0}^{3} [2]^2 \, dx$ = $\pi \int_{0}^{3} 4 \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = 4 x$$\text{,}$ $\text{so}$ $V$ = $\pi \left[F(3) - F(0)\right]$ = $\pi \left[4 \cdot 3 - \left(4 \cdot 0\right)\right]$ = $12 \pi$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{the}$ $\text{disc}$ $\text{method,}$ $\text{find}$ $\text{the}$ $\text{volume}$ $\text{of}$ $\text{the}$ $\text{solid}$ $\text{formed}$ $\text{by}$ $\text{revolving}$ $y = x^2 about the x-axis from x=0 to x=1$$\text{.}$', '["$\\pi/3$", "$-\\pi/5$", "$2\\pi/5$", "$\\pi/5$"]'::jsonb, 3, '$V$ = $\pi \int_{0}^{1} [x^{2}]^2 \, dx$ = $\pi \int_{0}^{1} x^{4} \, dx$$\text{.}$ $\text{An}$ $\text{antiderivative}$ $\text{of}$ $\text{the}$ $\text{integrand}$ $\text{is}$ $F(x) = \frac{x^{5}}{5}$$\text{,}$ $\text{so}$ $V$ = $\pi \left[F(1) - F(0)\right]$ = $\pi \left[\frac{1^{5}}{5} - \left(\frac{0^{5}}{5}\right)\right]$ = $\frac{\pi}{5}$$\text{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(3x^2 + 5)$$\text{.}$', '["$-6x/(3x^2 + 5)$", "$1/(3x^2 + 5)$", "$6x/(3x^2 + 5)$", "$6x$"]'::jsonb, 2, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = 3 x^{2} + 5$$\text{,}$ $u'' = 6 x$$\text{,}$ $\text{giving}$ $f''(x)$ = $\dfrac{6 x}{3 x^{2} + 5}$ = $\frac{6 x}{3 x^{2} + 5}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(\cos(x))$$\text{.}$', '["$1/\\cos(x)$", "$-\\sin(x)$", "$\\tan(x)$", "$-\\tan(x)$"]'::jsonb, 3, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = \cos{\left(x \right)}$$\text{,}$ $u'' = - \sin{\left(x \right)}$$\text{,}$ $\text{giving}$ $f''(x)$ = $\dfrac{- \sin{\left(x \right)}}{\cos{\left(x \right)}}$ = $- \tan{\left(x \right)}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(x^3 - 2)$$\text{.}$', '["$1/(x^3 - 2)$", "$3x^2/(x^3 - 2)$", "$-3x^2/(x^3 - 2)$", "$3x^2$"]'::jsonb, 1, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = x^{3} - 2$$\text{,}$ $u'' = 3 x^{2}$$\text{,}$ $\text{giving}$ $f''(x)$ = $\dfrac{3 x^{2}}{x^{3} - 2}$ = $\frac{3 x^{2}}{x^{3} - 2}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = \ln(5x - 1)$$\text{.}$', '["$-5/(5x - 1)$", "$5$", "$5/(5x - 1)$", "$1/(5x - 1)$"]'::jsonb, 2, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\text{.}$ $\text{With}$ $u = 5 x - 1$$\text{,}$ $u'' = 5$$\text{,}$ $\text{giving}$ $f''(x)$ = $\dfrac{5}{5 x - 1}$ = $\frac{5}{5 x - 1}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{4x}$$\text{.}$', '["$-4e^{4x}$", "$4e^{4x}$", "$e^{4x}$", "$4$"]'::jsonb, 1, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = 4 x$$\text{,}$ $u'' = 4$$\text{,}$ $\text{giving}$ $f''(x) = e^{4 x} \cdot 4 = 4 e^{4 x}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{x^2}$$\text{.}$', '["$\\text{-2xe\\textasciicircum{}(x\\textasciicircum{}2)}$", "$2x$", "$\\text{2xe\\textasciicircum{}(x\\textasciicircum{}2)}$", "$e^{x^2}$"]'::jsonb, 2, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = x^{2}$$\text{,}$ $u'' = 2 x$$\text{,}$ $\text{giving}$ $f''(x)$ = $e^{x^{2}} \cdot 2 x$ = $2 x e^{x^{2}}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{\sin(x)}$$\text{.}$', '["$e^{\\sin(x)}$", "$\\cos(x)$", "$-e^{\\sin(x)}\\cos(x)$", "$e^{\\sin(x)}\\cos(x)$"]'::jsonb, 3, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = \sin{\left(x \right)}$$\text{,}$ $u'' = \cos{\left(x \right)}$$\text{,}$ $\text{giving}$ $f''(x)$ = $e^{\sin{\left(x \right)}} \cdot \cos{\left(x \right)}$ = $e^{\sin{\left(x \right)}} \cos{\left(x \right)}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = e^{2x - 1}$$\text{.}$', '["$2$", "$2e^{2x - 1}$", "$-2e^{2x - 1}$", "$e^{2x - 1}$"]'::jsonb, 1, '$\text{By}$ $\text{the}$ $\text{Chain}$ $\text{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\text{.}$ $\text{With}$ $u = 2 x - 1$$\text{,}$ $u'' = 2$$\text{,}$ $\text{giving}$ $f''(x)$ = $e^{2 x - 1} \cdot 2$ = $2 e^{2 x - 1}$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = a \sin(x)$$\text{.}$', '["$-1/sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$1/sqrt{1 - x^2}$", "$sqrt{1 - x^2}$"]'::jsonb, 2, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{derivative}$ $\text{formula}$ $\text{for}$ $\text{inverse}$ $\text{trigonometric}$ $\text{functions:}$ $\dfrac{d}{dx}[\arcsin(x)]$ = $\frac{1}{\sqrt{1 - x^{2}}}$$\text{.}$', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = a \cos(x)$$\text{.}$', '["$1/sqrt{1 - x^2}$", "$sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/sqrt{1 - x^2}$"]'::jsonb, 3, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{derivative}$ $\text{formula}$ $\text{for}$ $\text{inverse}$ $\text{trigonometric}$ $\text{functions:}$ $\dfrac{d}{dx}[\arccos(x)]$ = $- \frac{1}{\sqrt{1 - x^{2}}}$$\text{.}$', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\text{the}$ $\text{derivative}$ $\text{of}$ $f(x) = a \tan(x)$$\text{.}$', '["$sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/(x^2 + 1)$", "$1/sqrt{1 - x^2}$"]'::jsonb, 1, '$\text{Using}$ $\text{the}$ $\text{standard}$ $\text{derivative}$ $\text{formula}$ $\text{for}$ $\text{inverse}$ $\text{trigonometric}$ $\text{functions:}$ $\dfrac{d}{dx}[\arctan(x)]$ = $\frac{1}{x^{2} + 1}$$\text{.}$', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = \ln(x^2 + 1)$$\text{,}$ $\text{find}$ $f''(2)$$\text{.}$', '["$4/3$", "$2/5$", "$1/5$", "$4/5$"]'::jsonb, 3, '$f''(x)$ = $\dfrac{d}{dx}[\ln(u)]$ = $\dfrac{u''}{u}$ $\text{with}$ $u = x^{2} + 1$$\text{:}$ $f''(x) = \frac{2 x}{x^{2} + 1}$$\text{.}$ $\text{At}$ $x=2$$\text{:}$ $f''(2)$ = $\frac{2 \cdot 2}{2^{2} + 1}$ = $\frac{4}{5}$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{If}$ $f(x) = e^{3x}$$\text{,}$ $\text{find}$ $f''(0)$$\text{.}$', '["$e^{3}$", "$0$", "$3$", "$1$"]'::jsonb, 2, '$f''(x)$ = $\dfrac{d}{dx}[e^u]$ = $e^u \cdot u''$ $\text{with}$ $u = 3 x$$\text{:}$ $f''(x) = 3 e^{3 x}$$\text{.}$ $\text{At}$ $x=0$$\text{:}$ $f''(0) = 3 e^{3 \cdot 0} = 3$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 1/x \, dx$$\text{.}$', '["$1/x^2 + C$", "$-1/x^2 + C$", "$ln|x| + C$", "$x \\cdot \\ln(x) + C$"]'::jsonb, 2, '$\text{With}$ $u = x$$\text{,}$ $du = 1 \, dx$$\text{.}$ $\int \dfrac{1}{x} \, dx$ = $\int \dfrac{1}{u} \, du$ = $\ln|u| + C$ = $\ln|x| + C$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int 2/(2x+1) \, dx$$\text{.}$', '["$2ln|2x+1| + C$", "$ln|x| + C$", "$(1/2)ln|2x+1| + C$", "$ln|2x+1| + C$"]'::jsonb, 3, '$\text{With}$ $u = 2 x + 1$$\text{,}$ $du = 2 \, dx$$\text{.}$ $\int \dfrac{2}{2 x + 1} \, dx$ = $\int \dfrac{1}{u} \, du$ = $\ln|u| + C$ = $\ln|2 x + 1| + C$$\text{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int e^{5x} \, dx$$\text{.}$', '["$(1/5)e^{5x} + C$", "$5e^{5x} + C$", "$e^{5x} + C$", "$e^{5x}/x + C$"]'::jsonb, 0, '$\text{With}$ $u = 5 x$$\text{,}$ $du = 5 \, dx$$\text{.}$ $\int e^{5 x} \, dx$ = $\dfrac{1}{5} \int e^u \, du$ = $\dfrac{1}{5} e^u + C$ = $\dfrac{1}{5} e^{5 x} + C$$\text{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int (3x + 5)^4 \, dx$$\text{.}$', '["$81x^5/5$ + $135x^4$ + $450x^3$ + $750x^2$ + $625x$ + $C$", "$243x^5/5$ + $405x^4$ + $1350x^3$ + $2250x^2$ + $1875x$ + $C$", "$-81x^5/5$ - $135x^4$ - $450x^3$ - $750x^2$ - $625x$ + $C$", "$324x^3 + 1620x^2 + 2700x + 1500 + C$"]'::jsonb, 0, '$\text{Let}$ $u = 3 x + 5$$\text{,}$ $\text{so}$ $du = 3 \, dx$$\text{.}$ $\int \left(3 x + 5\right)^{4} \, dx$ = $\dfrac{1}{3} \int u^{4} \, du$ = $\dfrac{1}{3} \cdot \dfrac{u^{5}}{5} + C$$\text{.}$ $\text{Substituting}$ $\text{back}$ $u = 3 x + 5$ $\text{and}$ $\text{expanding:}$ $\int \left(3 x + 5\right)^{4} \, dx$ = $\frac{81 x^{5}}{5}$ + $135 x^{4}$ + $450 x^{3}$ + $750 x^{2}$ + $625 x$ + $C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int \cos(2x + 1) \, dx$$\text{.}$', '["$-\\sin(2x + 1)/2 + C$", "$3 \\sin(2x + 1)/2 + C$", "$\\sin(2x + 1)/2 + C$", "$-2 \\sin(2x + 1) + C$"]'::jsonb, 2, '$\text{Let}$ $u = 2 x + 1$$\text{,}$ $\text{so}$ $du = 2 \, dx$$\text{.}$ $\int \cos(2 x + 1) \, dx$ = $\dfrac{1}{2} \int \cos(u) \, du$ = $\dfrac{1}{2} \sin(u) + C$$\text{.}$ $\text{Substituting}$ $\text{back}$ $u = 2 x + 1$$\text{:}$ $\int \cos(2 x + 1) \, dx$ = $\frac{\sin{\left(2 x + 1 \right)}}{2}$ + $C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int (4 - 3x)^3 \, dx$$\text{.}$', '["$-81x^2 + 216x - 144 + C$", "$-81x^4/4 + 108x^3 - 216x^2 + 192x + C$", "$27x^4/4 - 36x^3 + 72x^2 - 64x + C$", "$-27x^4/4 + 36x^3 - 72x^2 + 64x + C$"]'::jsonb, 3, '$\text{Let}$ $u = 4 - 3 x$$\text{,}$ $\text{so}$ $du = -3 \, dx$$\text{.}$ $\int \left(4 - 3 x\right)^{3} \, dx$ = $\dfrac{1}{-3} \int u^{3} \, du$ = $\dfrac{1}{-3} \cdot \dfrac{u^{4}}{4} + C$$\text{.}$ $\text{Substituting}$ $\text{back}$ $u = 4 - 3 x$ $\text{and}$ $\text{expanding:}$ $\int \left(4 - 3 x\right)^{3} \, dx$ = $- \frac{27 x^{4}}{4}$ + $36 x^{3}$ - $72 x^{2}$ + $64 x$ + $C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{substitution,}$ $\text{find}$ $\int \sin(5x) \, dx$$\text{.}$', '["$-3 \\cos(5x)/5 + C$", "$-\\cos(5x)/5 + C$", "$\\cos(5x)/5 + C$", "$5 \\cos(5x) + C$"]'::jsonb, 1, '$\text{Using}$ $\text{an}$ $\text{appropriate}$ $\text{substitution}$ $\text{for}$ $\text{the}$ $\text{inner}$ $\text{expression,}$ $\int \sin{\left(5 x \right)} \, dx$ = $- \frac{\cos{\left(5 x \right)}}{5} + C$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{1} 2x(x^2 + 1)^3 \, dx$$\text{.}$', '["$15/4$", "$15/2$", "$-15/4$", "$19/4$"]'::jsonb, 0, '$\text{Using}$ $\text{substitution,}$ $\text{an}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ = $\frac{x^{8}}{4}$ + $x^{6}$ + $\frac{3 x^{4}}{2}$ + $x^{2}$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $x=0$ $\text{to}$ $x=1$$\text{:}$ $F(1) - F(0)$ = $\frac{15}{4} - 0$ = $\frac{15}{4}$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{pi/2} \sin(x)^2 \cos(x) \, dx$$\text{.}$', '["$2/3$", "$1/3$", "$-1/3$", "$4/3$"]'::jsonb, 1, '$\text{Using}$ $\text{substitution,}$ $\text{an}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ = $\frac{\sin^{3}{\left(x \right)}}{3}$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $x=0$ $\text{to}$ $x=\frac{\pi}{2}$$\text{:}$ $F(\frac{\pi}{2}) - F(0)$ = $\frac{1}{3} - 0$ = $\frac{1}{3}$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{2} x/(x^2 + 4) \, dx$$\text{.}$', '["$3 \\log(2)/2$", "$-\\ln(2)/2$", "$\\ln(2)/2$", "$\\ln(2)$"]'::jsonb, 2, '$\text{Using}$ $\text{substitution,}$ $\text{an}$ $\text{antiderivative}$ $\text{is}$ $F(x)$ = $\frac{\log{\left(x^{2} + 4 \right)}}{2}$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $x=0$ $\text{to}$ $x=2$$\text{:}$ $F(2) - F(0)$ = $\log{\left(2 \sqrt{2} \right)}$ - $\log{\left(2 \right)}$ = $\log{\left(\sqrt{2} \right)}$$\text{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{Integration}$ $\text{by}$ $\text{Parts,}$ $\text{find}$ $\int xe^{x} \, dx$$\text{.}$', '["$\\text{xe\\textasciicircum{}(x)}$ $\\text{+}$ $\\text{C}$", "$(1 - x)e^{x} + C$", "$(x - 1)e^{x} + C$", "$x^2e^{x}/2 + C$"]'::jsonb, 2, '$\text{With}$ $u = x$ $\text{and}$ $dv = e^{x} \, dx$$\text{:}$ $du = dx$ $\text{and}$ $v = e^{x}$$\text{.}$ $\text{Integration}$ $\text{by}$ $\text{parts,}$ $\int u \, dv = uv - \int v \, du$$\text{,}$ $\text{gives}$ $\int x e^{x} \, dx$ = $xe^{x} - \int e^{x} \, dx$ = $\left(x - 1\right) e^{x} + C$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{Integration}$ $\text{by}$ $\text{Parts,}$ $\text{find}$ $\int x \sin(x) \, dx$$\text{.}$', '["$-x \\cos(x) + \\sin(x) + C$", "$-x \\cos(x) + C$", "$-x^2 \\cos(x)/2 + C$", "$x \\cos(x) - \\sin(x) + C$"]'::jsonb, 0, '$\text{With}$ $u = x$ $\text{and}$ $dv = \sin{\left(x \right)} \, dx$$\text{:}$ $du = dx$ $\text{and}$ $v = - \cos{\left(x \right)}$$\text{.}$ $\text{Integration}$ $\text{by}$ $\text{parts,}$ $\int u \, dv = uv - \int v \, du$$\text{,}$ $\text{gives}$ $\int x \sin{\left(x \right)} \, dx$ = $x- \cos{\left(x \right)}$ - $\int$ - $\cos{\left(x \right)} \, dx$ = $- x \cos{\left(x \right)}$ + $\sin{\left(x \right)}$ + $C$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Using}$ $\text{Integration}$ $\text{by}$ $\text{Parts,}$ $\text{find}$ $\int x \cos(x) \, dx$$\text{.}$', '["$-x \\sin(x) - \\cos(x) + C$", "$x^2 \\sin(x)/2 + C$", "$x \\sin(x) + C$", "$x \\sin(x) + \\cos(x) + C$"]'::jsonb, 3, '$\text{With}$ $u = x$ $\text{and}$ $dv = \cos{\left(x \right)} \, dx$$\text{:}$ $du = dx$ $\text{and}$ $v = \sin{\left(x \right)}$$\text{.}$ $\text{Integration}$ $\text{by}$ $\text{parts,}$ $\int u \, dv = uv - \int v \, du$$\text{,}$ $\text{gives}$ $\int x \cos{\left(x \right)} \, dx$ = $x\sin{\left(x \right)}$ - $\int \sin{\left(x \right)} \, dx$ = $x \sin{\left(x \right)}$ + $\cos{\left(x \right)}$ + $C$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Evaluate}$ $\int_{0}^{1} x \cdot e^x \, dx$$\text{.}$', '["$-1 + E$", "$\\text{E}$", "$0$", "$1$"]'::jsonb, 3, '$\text{Using}$ $\text{integration}$ $\text{by}$ $\text{parts}$ $\text{with}$ $u = x$$\text{,}$ $dv = e^{x} \, dx$$\text{:}$ $v = e^{x}$$\text{,}$ $\text{so}$ $\int x \, e^{x} \, dx$ = $xe^{x} - \int e^{x} \, dx$ = $\left(x - 1\right) e^{x} + C$$\text{.}$ $\text{Evaluating}$ $\text{from}$ $0$ $\text{to}$ $1$$\text{:}$ $(\left(-1 + 1\right) e^{1})$ - $(\left(-1 + 0\right) e^{0})$ = $0 - -1$ = $1$$\text{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\text{Find}$ $\int \tan(x) \, dx$$\text{.}$', '["$ln|\\sec(x)| + C$", "$ln|\\cos(x)| + C$", "$\\sec(x)\\tan(x) + C$", "$ln|\\sin(x)| + C$"]'::jsonb, 0, '$\text{Writing}$ $\tan(x) = \sin(x)/\cos(x)$ $\text{and}$ $\text{substituting}$ $v = \cos(x)$ $\text{(so}$ $dv = -\sin(x) \, dx$$\text{)}$ $\text{gives}$ $\int \tan(x) \, dx = -\ln|\cos(x)| + C$$\text{,}$ $\text{which}$ $\text{is}$ $\text{the}$ $\text{same}$ $\text{as}$ $\ln|\sec(x)| + C$ $\text{(since}$ $-\ln|\cos(x)|$ = $\ln|\cos(x)|^{-1}$ = $\ln|\sec(x)|$$\text{).}$', 'Method of Substitution', false);
